-- ===================== 20260926000300_automation.sql =====================

-- =====================================================================
-- GAARD Capital CRM · Migration 3 of 6 · Automation
--
-- The rules Jon does by hand today, done by the database:
--   * duplicate keys + flag rules (university, do-not-contact) on save
--   * outreach emails start as "No response"
--   * a confirmed outcome sets the next outreach date and the reminder
--     (OOO -> 2 weeks, "check back in October" -> Oct 1, no reply -> quarterly)
--   * call booked -> opportunity opened + added to the quarterly newsletter
--   * unsubscribe -> do-not-contact, and outreach to that person is blocked
--   * RFP status changes flow into the pipeline
--
-- The mock-data seed sets app.seeding = 'on' so these rules do not fire
-- while history is being loaded (the seed already contains the results).
-- =====================================================================

-- ---------------------------------------------------------------------
-- Small helpers
-- ---------------------------------------------------------------------

create or replace function public.automation_enabled() returns boolean
language sql stable set search_path = '' as $$
  select coalesce(current_setting('app.seeding', true), 'off') <> 'on'
$$;

-- the team works in Mountain time; dates are taken in that zone
create or replace function public.local_date(p timestamptz) returns date
language sql stable set search_path = '' as $$
  select (p at time zone 'America/Denver')::date
$$;

create or replace function public.local_today() returns date
language sql stable set search_path = '' as $$
  select (now() at time zone 'America/Denver')::date
$$;

create or replace function public.stage_rank(p_stage text) returns int
language sql stable set search_path = '' as $$
  select sort_order from public.pipeline_stages where code = p_stage
$$;

create or replace function public.add_to_newsletter(p_contact_id bigint, p_on date, p_via text) returns void
language sql set search_path = '' as $$
  update public.contacts
     set newsletter_status = 'subscribed', newsletter_added_on = p_on, newsletter_added_via = p_via
   where id = p_contact_id and newsletter_status = 'not_subscribed' and not do_not_contact;
$$;

create or replace function public.set_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;


-- ---------------------------------------------------------------------
-- Organizations: flag rules on save
-- ---------------------------------------------------------------------

create or replace function public.organizations_before_write() returns trigger
language plpgsql set search_path = public as $$
declare
  r        flag_rules;
  v_domain text := norm_domain(new.website);
  v_key    text := norm_org_name(new.name);
begin
  if (select party_type from segments where code = new.segment_code) = 'individual' then
    raise exception 'Segment % is for individuals. Add the person as a contact without an organization.', new.segment_code;
  end if;

  for r in select * from flag_rules where is_active loop
    if (r.match_on = 'org_name' and v_key like '%' || norm_org_name(r.pattern) || '%')
       or (r.match_on = 'email_domain' and domain_matches(v_domain, r.pattern)) then
      if r.flag = 'university' then
        new.is_university_affiliated := true;
      elsif not new.do_not_contact then
        new.do_not_contact := true;
        new.dnc_reason := coalesce(new.dnc_reason, r.reason, 'Matches the do-not-contact list');
      end if;
    end if;
  end loop;

  if not new.do_not_contact then new.dnc_reason := null; end if;
  if tg_op = 'UPDATE' then new.updated_at := now(); end if;
  return new;
end $$;

-- when an organization gets flagged, its people inherit the flag
create or replace function public.organizations_after_write() returns trigger
language plpgsql set search_path = public as $$
begin
  if (new.do_not_contact and not old.do_not_contact)
     or (new.is_university_affiliated and not old.is_university_affiliated) then
    update contacts set updated_at = now() where organization_id = new.id;   -- re-runs contacts_before_write
  end if;
  return null;
end $$;

create trigger organizations_before_write before insert or update on public.organizations
  for each row execute function public.organizations_before_write();
create trigger organizations_after_write after update on public.organizations
  for each row execute function public.organizations_after_write();


-- ---------------------------------------------------------------------
-- Contacts: defaults from the organization + flag rules on save
-- ---------------------------------------------------------------------

create or replace function public.contacts_before_write() returns trigger
language plpgsql set search_path = public as $$
declare
  o        organizations;
  r        flag_rules;
  v_email  text := norm_email(new.email);
  v_domain text := nullif(split_part(norm_email(new.email), '@', 2), '');
  v_li     text := norm_linkedin(new.linkedin_url);
begin
  if new.organization_id is not null then
    select * into o from organizations where id = new.organization_id;
    new.segment_code := coalesce(new.segment_code, o.segment_code);
    new.state        := coalesce(new.state, o.state);
    new.city         := coalesce(new.city, o.city);
    if o.do_not_contact and not new.do_not_contact then
      new.do_not_contact := true;
      new.dnc_reason := coalesce(new.dnc_reason, 'Organization is on the do-not-contact list: ' || coalesce(o.dnc_reason, 'no reason given'));
    end if;
    if o.is_university_affiliated then new.is_university_affiliated := true; end if;
  end if;

  for r in select * from flag_rules where is_active loop
    if (r.match_on = 'email_domain' and domain_matches(v_domain, r.pattern))
       or (r.match_on = 'email'    and v_email = norm_email(r.pattern))
       or (r.match_on = 'linkedin' and v_li    = norm_linkedin(r.pattern)) then
      if r.flag = 'university' then
        new.is_university_affiliated := true;
      elsif not new.do_not_contact then
        new.do_not_contact := true;
        new.dnc_reason := coalesce(new.dnc_reason, r.reason, 'Matches the do-not-contact list');
      end if;
    end if;
  end loop;

  if new.do_not_contact then
    new.dnc_on := coalesce(new.dnc_on, local_today());
    if new.newsletter_status = 'subscribed' then new.newsletter_status := 'unsubscribed'; end if;
  else
    new.dnc_on := null;
    new.dnc_reason := null;
  end if;

  -- a corrected email address starts fresh (off the wrong-email list)
  if tg_op = 'UPDATE' and v_email is distinct from norm_email(old.email)
     and new.email_status = old.email_status and new.email_status in ('bounced', 'wrong_person') then
    new.email_status := 'unverified';
  end if;

  if tg_op = 'UPDATE' then new.updated_at := now(); end if;
  return new;
end $$;

-- fixing the email or phone closes the "fix contact info" reminder
create or replace function public.contacts_after_update() returns trigger
language plpgsql set search_path = public as $$
begin
  if automation_enabled()
     and (norm_email(new.email) is distinct from norm_email(old.email) or new.phone is distinct from old.phone) then
    update reminders set status = 'done', completed_at = now()
     where contact_id = new.id and reminder_type = 'fix_contact_info' and status in ('open', 'snoozed');
  end if;
  return null;
end $$;

create trigger contacts_before_write before insert or update on public.contacts
  for each row execute function public.contacts_before_write();
create trigger contacts_after_update after update on public.contacts
  for each row execute function public.contacts_after_update();


-- ---------------------------------------------------------------------
-- Touchpoints: guard rails before save
-- ---------------------------------------------------------------------

create or replace function public.touchpoints_before_write() returns trigger
language plpgsql set search_path = public as $$
declare
  c  contacts;
  tt touch_types;
  o  outcomes;
begin
  select * into c  from contacts    where id   = new.contact_id;
  select * into tt from touch_types where code = new.touch_type;
  new.organization_id := coalesce(new.organization_id, c.organization_id);
  new.owner_id        := coalesce(new.owner_id, c.owner_id);

  -- do-not-contact: block new emails / calls after someone is flagged
  if tg_op = 'INSERT' and new.direction = 'outbound' and new.touch_type in ('email', 'call', 'check_in')
     and c.do_not_contact and (c.dnc_on is null or local_date(new.touched_at) > c.dnc_on) then
    raise exception 'DO NOT CONTACT: % is on the do-not-contact list (%)',
                    coalesce(c.full_name, c.email), coalesce(c.dnc_reason, 'no reason given')
      using hint = 'Remove the flag on the contact, or the matching flag rule, if this is intentional.';
  end if;

  -- outreach emails start as "No response" until a reply comes in
  if new.outcome_code is null and new.direction = 'outbound' and new.touch_type in ('email', 'check_in') then
    new.outcome_code := 'NO_RESPONSE';
  end if;

  -- the outcome has to fit the kind of touch
  if new.outcome_code is not null then
    select * into o from outcomes where code = new.outcome_code;
    if not (new.touch_type = any (o.applies_to)) then
      raise exception 'Outcome "%" cannot be used on a "%" touch (allowed on: %)',
                      o.label, tt.name, array_to_string(o.applies_to, ', ');
    end if;
  end if;
  if new.ai_suggested_outcome is not null and not exists (
       select 1 from outcomes where code = new.ai_suggested_outcome and new.touch_type = any (applies_to)) then
    raise exception 'Suggested outcome % does not fit a "%" touch', new.ai_suggested_outcome, tt.name;
  end if;

  -- a person confirmed a suggested outcome
  if tg_op = 'UPDATE' and new.outcome_status = 'confirmed' and old.outcome_status = 'needs_review' then
    new.confirmed_at := coalesce(new.confirmed_at, now());
  end if;

  if tg_op = 'UPDATE' then new.updated_at := now(); end if;
  return new;
end $$;

create trigger touchpoints_before_write before insert or update on public.touchpoints
  for each row execute function public.touchpoints_before_write();


-- ---------------------------------------------------------------------
-- The outcome rules (runs after a touchpoint's outcome is confirmed)
-- ---------------------------------------------------------------------

create or replace function public.apply_outcome_rules(p_touch public.touchpoints) returns void
language plpgsql set search_path = public as $$
declare
  o          outcomes;
  c          contacts;
  seg        segments;
  tt         touch_types;
  v_day      date := local_date(p_touch.touched_at);
  v_label    text;
  v_dnc      boolean;
  v_due      date;
  v_opp      opportunities;
  v_latest   boolean;
  v_streak   int;
begin
  select * into o   from outcomes    where code = p_touch.outcome_code;
  if not found then return; end if;
  select * into c   from contacts    where id   = p_touch.contact_id;
  select * into seg from segments    where code = c.segment_code;
  select * into tt  from touch_types where code = p_touch.touch_type;
  v_label := coalesce(c.full_name, c.email, 'Contact #' || c.id)
             || coalesce(' (' || (select name from organizations where id = c.organization_id) || ')', '');

  -- 1. contact flags ----------------------------------------------------
  if o.sets_do_not_contact then
    update contacts
       set do_not_contact = true,
           dnc_reason     = coalesce(dnc_reason, o.label),
           dnc_on         = coalesce(dnc_on, v_day)
     where id = c.id;
    update reminders set status = 'dismissed', completed_at = now()
     where contact_id = c.id and status in ('open', 'snoozed');
  end if;

  if p_touch.touch_type in ('email', 'check_in') then
    if o.marks_email_bad then
      update contacts set email_status = 'bounced' where id = c.id;
    elsif o.code = 'WRONG_PERSON' then
      update contacts set email_status = 'wrong_person' where id = c.id;
    elsif o.counts_as_response then
      update contacts set email_status = 'valid' where id = c.id and email_status <> 'valid';
    end if;
  end if;

  if o.adds_to_newsletter then
    perform add_to_newsletter(c.id, v_day, 'auto: ' || o.label);
  end if;

  v_dnc := c.do_not_contact or o.sets_do_not_contact;

  -- 2. next outreach date = the reminder ----------------------------------
  -- only the most recent touch sets the cadence (back-filled history does not)
  v_latest := not exists (
    select 1 from touchpoints t
     where t.contact_id = c.id and t.id <> p_touch.id and t.touched_at > p_touch.touched_at);

  if v_latest then
    update reminders set status = 'superseded', completed_at = now()
     where contact_id = c.id and status in ('open', 'snoozed')
       and reminder_type in ('follow_up', 'ooo_follow_up', 'post_call', 'event_follow_up',
                             'referral_follow_up', 'check_in');

    if o.reminder_type is not null and not v_dnc then
      -- e.g. the 3rd unanswered dial in a row: stop calling weekly, go back to quarterly
      if o.retry_limit is not null then
        select count(*) into v_streak
          from touchpoints t join outcomes x on x.code = t.outcome_code
         where t.contact_id = c.id and t.touch_type = p_touch.touch_type and x.retry_limit is not null
           and t.touched_at <= p_touch.touched_at
           and t.touched_at > coalesce((select max(t2.touched_at) from touchpoints t2
                                          join outcomes x2 on x2.code = t2.outcome_code
                                         where t2.contact_id = c.id and x2.retry_limit is null
                                           and t2.touched_at <= p_touch.touched_at), '-infinity');
      end if;
      v_due := coalesce(
        p_touch.follow_up_on,                                                   -- "check back in October"
        case when o.code = 'OUT_OF_OFFICE' then p_touch.ooo_return_on + 1 end, -- back from vacation
        case when v_streak >= o.retry_limit then v_day + o.after_limit_days end,
        v_day + o.next_outreach_days);                                          -- default cadence
      if v_due is not null then
        insert into reminders (reminder_type, contact_id, organization_id, touchpoint_id, due_on,
                               title, details, follow_up_style, assigned_to)
        values (o.reminder_type, c.id, c.organization_id, p_touch.id, v_due,
                (select label from reminder_types where code = o.reminder_type) || ': ' || v_label,
                'Last outcome: ' || o.label || ' (' || tt.name || ', ' || to_char(v_day, 'Mon DD, YYYY') || ')'
                  || coalesce(E'\n' || p_touch.notes, ''),
                c.follow_up_style, c.owner_id);
      end if;
    end if;
  end if;

  -- 3. pipeline -----------------------------------------------------------
  if o.sets_stage is not null then
    -- the open opportunity for this person, or for their organization
    select * into v_opp from opportunities op
     where op.stage not in ('funded', 'lost')
       and (op.contact_id = c.id
            or (seg.party_type = 'organization' and c.organization_id is not null
                and op.organization_id = c.organization_id))
     order by (op.contact_id = c.id) desc, op.opened_on desc
     limit 1;

    if found then
      if o.sets_stage = 'lost' then
        update opportunities
           set stage = 'lost', closed_on = coalesce(closed_on, v_day), lost_reason = coalesce(lost_reason, o.label)
         where id = v_opp.id;
      else
        update opportunities
           set stage = case when stage_rank(o.sets_stage) > stage_rank(v_opp.stage) then o.sets_stage else stage end,
               first_call_on = coalesce(first_call_on, case when p_touch.touch_type = 'meeting' then v_day end),
               hot_on = case when o.sets_stage = 'hot' then coalesce(hot_on, v_day) else hot_on end,
               onboarding_started_on = case when o.sets_stage = 'onboarding'
                                            then coalesce(onboarding_started_on, v_day) else onboarding_started_on end
         where id = v_opp.id;
      end if;
    elsif o.sets_stage <> 'lost' then
      -- a call was just booked: open the opportunity
      insert into opportunities (contact_id, organization_id, segment_code, state, stage,
                                 source_channel_code, converting_channel_code, converting_touchpoint_id,
                                 source_event_id, rfp_id, opened_on, first_call_on, hot_on,
                                 onboarding_started_on, owner_id)
      values (c.id,
              case when seg.party_type = 'organization' then c.organization_id end,
              c.segment_code, c.state, o.sets_stage,
              coalesce(c.source_channel_code, tt.channel_code, 'COLD_EMAIL'),
              tt.channel_code, p_touch.id, c.source_event_id, p_touch.rfp_id, v_day,
              case when p_touch.touch_type = 'meeting' then v_day else p_touch.follow_up_on end,
              case when o.sets_stage = 'hot' then v_day end,
              case when o.sets_stage = 'onboarding' then v_day end,
              c.owner_id);
    end if;
  end if;
end $$;

create or replace function public.touchpoints_after_write() returns trigger
language plpgsql set search_path = public as $$
begin
  if not automation_enabled() then return null; end if;
  if new.outcome_status = 'confirmed' and new.outcome_code is not null and (
       tg_op = 'INSERT'
       or old.outcome_code   is distinct from new.outcome_code
       or old.outcome_status is distinct from new.outcome_status
       or old.follow_up_on   is distinct from new.follow_up_on
       or old.ooo_return_on  is distinct from new.ooo_return_on) then
    perform apply_outcome_rules(new);
  end if;
  return null;
end $$;

create trigger touchpoints_after_write after insert or update on public.touchpoints
  for each row execute function public.touchpoints_after_write();


-- ---------------------------------------------------------------------
-- Opportunities: defaults, stage dates, newsletter
-- ---------------------------------------------------------------------

create or replace function public.opportunities_before_write() returns trigger
language plpgsql set search_path = public as $$
declare
  c   contacts;
  seg segments;
begin
  select * into c from contacts where id = new.contact_id;
  new.segment_code := coalesce(new.segment_code, c.segment_code);
  new.state        := coalesce(new.state, c.state);
  select * into seg from segments where code = new.segment_code;

  if tg_op = 'INSERT' then
    if new.organization_id is null and seg.party_type = 'organization' then
      new.organization_id := c.organization_id;
    end if;
    new.source_channel_code := coalesce(new.source_channel_code, c.source_channel_code, new.converting_channel_code);
    new.source_event_id     := coalesce(new.source_event_id, c.source_event_id);
    new.owner_id            := coalesce(new.owner_id, c.owner_id);
    new.opened_on           := coalesce(new.opened_on, local_today());
  end if;

  -- moving the stage by hand stamps the milestone date
  if tg_op = 'UPDATE' and new.stage is distinct from old.stage then
    case new.stage
      when 'hot'        then new.hot_on                := coalesce(new.hot_on, local_today());
      when 'onboarding' then new.onboarding_started_on := coalesce(new.onboarding_started_on, local_today());
      when 'funded'     then new.funded_on             := coalesce(new.funded_on, local_today());
      when 'lost'       then new.closed_on             := coalesce(new.closed_on, local_today());
      else null;
    end case;
  end if;
  if new.stage = 'funded' then new.closed_on := coalesce(new.closed_on, new.funded_on); end if;

  if tg_op = 'UPDATE' then new.updated_at := now(); end if;
  return new;
end $$;

-- Jon: "every time we have a call with someone, we want to put them on
-- this quarterly newsletter list"
create or replace function public.opportunities_after_insert() returns trigger
language plpgsql set search_path = public as $$
begin
  if automation_enabled() then
    perform add_to_newsletter(new.contact_id, new.opened_on, 'auto: call booked');
  end if;
  return null;
end $$;

create trigger opportunities_before_write before insert or update on public.opportunities
  for each row execute function public.opportunities_before_write();
create trigger opportunities_after_insert after insert on public.opportunities
  for each row execute function public.opportunities_after_insert();


-- ---------------------------------------------------------------------
-- RFPs: deadline reminders, and status changes flow into the pipeline
-- ---------------------------------------------------------------------

create or replace function public.rfps_after_write() returns trigger
language plpgsql set search_path = public as $$
declare
  v_outcome text;
  v_on      date;
begin
  if not automation_enabled() then return null; end if;

  if new.status in ('identified', 'intent_to_bid') and new.due_on is not null then
    update reminders set due_on = new.due_on - 7
     where rfp_id = new.id and reminder_type = 'rfp_deadline' and status in ('open', 'snoozed');
    if not found then
      insert into reminders (reminder_type, rfp_id, organization_id, contact_id, due_on, title, details, assigned_to)
      values ('rfp_deadline', new.id, new.organization_id, new.contact_id, new.due_on - 7,
              'RFP due ' || to_char(new.due_on, 'Mon DD') || ': ' || new.title,
              'Response due ' || to_char(new.due_on, 'Mon DD, YYYY') || '. Reminder set a week ahead.',
              new.owner_id);
    end if;
  else
    update reminders set status = 'done', completed_at = now()
     where rfp_id = new.id and reminder_type = 'rfp_deadline' and status in ('open', 'snoozed');
  end if;

  if tg_op = 'UPDATE' and new.status is distinct from old.status and new.contact_id is not null then
    v_outcome := case new.status when 'submitted' then 'RFP_SUBMITTED' when 'finalist' then 'RFP_FINALIST'
                                 when 'won' then 'RFP_WON' when 'lost' then 'RFP_LOST' end;
    if v_outcome is not null then
      v_on := case when new.status = 'submitted' then coalesce(new.submitted_on, local_today())
                   else coalesce(new.decision_on, local_today()) end;
      insert into touchpoints (contact_id, organization_id, touch_type, direction, touched_at, rfp_id,
                               outcome_code, notes, owner_id)
      values (new.contact_id, new.organization_id, 'rfp', 'outbound',
              (v_on + time '12:00') at time zone 'America/Denver', new.id, v_outcome,
              'RFP status changed to ' || new.status || ': ' || new.title, new.owner_id);
    end if;
  end if;
  return null;
end $$;

create trigger rfps_set_updated_at before update on public.rfps
  for each row execute function public.set_updated_at();
create trigger rfps_after_write after insert or update on public.rfps
  for each row execute function public.rfps_after_write();


-- ---------------------------------------------------------------------
-- Functions the app calls (review queue, notifications tab)
-- ---------------------------------------------------------------------

-- Review queue: accept the suggested outcome (or pick another) in one click
create or replace function public.confirm_outcome(
  p_touchpoint_id bigint,
  p_outcome_code  text   default null,     -- NULL = accept the suggestion
  p_follow_up_on  date   default null,     -- e.g. the "check back in October" date
  p_confirmed_by  bigint default null
) returns public.touchpoints
language plpgsql set search_path = public as $$
declare
  t touchpoints;
begin
  update touchpoints
     set outcome_code   = coalesce(p_outcome_code, ai_suggested_outcome, outcome_code),
         follow_up_on   = coalesce(p_follow_up_on, follow_up_on),
         outcome_status = 'confirmed',
         confirmed_by   = p_confirmed_by,
         confirmed_at   = now()
   where id = p_touchpoint_id
  returning * into t;
  if not found then raise exception 'Touchpoint % not found', p_touchpoint_id; end if;
  return t;
end $$;

-- Notifications tab: done for one person = done for everyone
create or replace function public.complete_reminder(p_reminder_id bigint, p_by bigint default null) returns void
language sql set search_path = '' as $$
  update public.reminders set status = 'done', completed_by = p_by, completed_at = now()
   where id = p_reminder_id and status in ('open', 'snoozed');
$$;

create or replace function public.snooze_reminder(p_reminder_id bigint, p_until date) returns void
language sql set search_path = '' as $$
  update public.reminders set status = 'snoozed', snoozed_until = p_until, due_on = p_until
   where id = p_reminder_id and status in ('open', 'snoozed');
$$;

-- Daily job: snoozed reminders come back
create or replace function public.wake_snoozed_reminders() returns int
language plpgsql set search_path = public as $$
declare n int;
begin
  update reminders set status = 'open', snoozed_until = null
   where status = 'snoozed' and snoozed_until <= local_today();
  get diagnostics n = row_count;
  return n;
end $$;

-- Weekly job: open opportunities nobody has touched in a while
create or replace function public.flag_stale_opportunities(p_days int default 21) returns int
language plpgsql set search_path = public as $$
declare n int;
begin
  insert into reminders (reminder_type, contact_id, organization_id, opportunity_id, due_on, title, details,
                         assigned_to, created_by)
  select case when op.stage = 'onboarding' then 'onboarding_task' else 'post_call' end,
         op.contact_id, op.organization_id, op.id, local_today(),
         'No activity in ' || p_days || ' days: ' || coalesce(c.full_name, c.email)
           || coalesce(' (' || o.name || ')', ''),
         'Stage: ' || ps.label || '. Last touch: ' || coalesce(to_char(lt.last_at, 'Mon DD, YYYY'), 'none'),
         op.owner_id, 'system: stale check'
    from opportunities op
    join contacts c          on c.id = op.contact_id
    join pipeline_stages ps  on ps.code = op.stage
    left join organizations o on o.id = op.organization_id
    left join lateral (
      select max(t.touched_at) as last_at from touchpoints t
       where t.contact_id = op.contact_id
          or (op.organization_id is not null and t.organization_id = op.organization_id)) lt on true
   where op.stage in ('call', 'hot', 'onboarding')
     and coalesce(lt.last_at, op.opened_on::timestamptz) < now() - make_interval(days => p_days)
     and not exists (select 1 from reminders r
                      where r.status in ('open', 'snoozed')
                        and (r.opportunity_id = op.id or r.contact_id = op.contact_id));
  get diagnostics n = row_count;
  return n;
end $$;

-- After the one-time migration from the sheets (imported with p_run_automation => false):
-- give everyone the follow-up their latest outcome calls for, in one pass
create or replace function public.rebuild_follow_up_reminders() returns int
language plpgsql set search_path = public as $$
declare
  t touchpoints;
  n int := 0;
begin
  for t in
    select distinct on (tp.contact_id) tp.*
      from touchpoints tp
     where tp.outcome_status = 'confirmed' and tp.outcome_code is not null
       and not exists (select 1 from reminders r where r.contact_id = tp.contact_id and r.status in ('open', 'snoozed'))
     order by tp.contact_id, tp.touched_at desc, tp.id desc
  loop
    perform apply_outcome_rules(t);
    n := n + 1;
  end loop;
  return n;
end $$;

-- After loading Jon's flag list: re-check everyone against the rules
create or replace function public.reapply_flag_rules() returns int
language plpgsql set search_path = public as $$
declare n int;
begin
  update organizations set name = name;   -- re-runs organizations_before_write
  update contacts set email = email;      -- re-runs contacts_before_write
  get diagnostics n = row_count;
  return n;
end $$;

-- ===================== 20260926000400_import_pipeline.sql =====================

-- =====================================================================
-- GAARD Capital CRM · Migration 4 of 6 · Import pipeline
--
-- "We need something where we can just throw in a bunch of content and
--  then we know exactly whether or not we've already outreached to them."
--
-- 1. Put rows into import_rows (paste, CSV upload, or the app) using the
--    outreach sheet's own columns: Date, Source, Contact, First Name,
--    Email, Org, Website, LinkedIn, Added on LinkedIn, Notes,
--    Date Outreached, Outcome, Next Steps (+ optional Phone, AUM, State,
--    Segment, Title, Last Name).
-- 2. select process_import_batch(<batch id>);
-- 3. Each row comes back labelled:
--      new_contact               brand new person (and organization)
--      new_contact_existing_org  new person, organization already known;
--                                shows who was contacted there before
--      existing_contact          already in the CRM (email or LinkedIn)
--      needs_review              looks like a duplicate, a person decides
--      skipped / error           with the reason
-- Used once for the historical migration and then for every new batch.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Parsing helpers for spreadsheet text
-- ---------------------------------------------------------------------

-- '9/1/26', '09/01/2026', '2026-09-01', 'Sep 1, 2026' -> date (NULL if unreadable)
create or replace function public.parse_loose_date(p text) returns date
language plpgsql stable set search_path = '' as $$
declare
  s text := trim(coalesce(p, ''));
begin
  if s = '' then return null; end if;
  if s ~ '^\d{4}-\d{1,2}-\d{1,2}' then return to_date(substring(s from '^\d{4}-\d{1,2}-\d{1,2}'), 'YYYY-MM-DD'); end if;
  if s ~ '^\d{1,2}/\d{1,2}/\d{4}$' then return to_date(s, 'MM/DD/YYYY'); end if;
  if s ~ '^\d{1,2}/\d{1,2}/\d{2}$'  then return to_date(s, 'MM/DD/YY'); end if;
  if s ~ '^\d{1,2}/\d{1,2}$'        then return null; end if;          -- no year: too ambiguous
  return s::date;
exception when others then
  return null;
end $$;

-- '$12.5M', '12,500,000', '850k', '1.2 billion' -> numeric
create or replace function public.parse_amount(p text) returns numeric
language plpgsql immutable set search_path = '' as $$
declare
  s text;
  m text[];
begin
  s := lower(coalesce(p, ''));
  s := replace(replace(replace(s, 'billion', 'b'), 'million', 'm'), 'thousand', 'k');
  s := regexp_replace(s, '[\s$,~]|usd', '', 'g');
  m := regexp_match(s, '^(\d+(?:\.\d+)?)(k|m|mm|b|bn)?$');
  if m is null then return null; end if;
  return m[1]::numeric * case m[2] when 'k' then 1e3 when 'm' then 1e6 when 'mm' then 1e6
                                   when 'b' then 1e9 when 'bn' then 1e9 else 1 end;
end $$;

-- "Added on LinkedIn": 'Yes' / TRUE / 'x' / a date -> date connected
create or replace function public.parse_yes_or_date(p text, p_fallback date) returns date
language plpgsql stable set search_path = public as $$
declare
  s text := lower(trim(coalesce(p, '')));
begin
  if s in ('', 'no', 'n', 'false', 'f', '0', '-', 'n/a', 'na') then return null; end if;
  if s in ('yes', 'y', 'true', 't', 'x', '1', '✓', '✔', 'connected', 'added', 'done') then return p_fallback; end if;
  return coalesce(parse_loose_date(s), p_fallback);
end $$;

create or replace function public.resolve_state(p text) returns char(2)
language sql stable set search_path = '' as $$
  select code from public.us_states
   where code = upper(trim(p)) or lower(name) = lower(trim(p))
   limit 1
$$;

create or replace function public.resolve_segment(p text, p_default text) returns text
language sql stable set search_path = '' as $$
  select coalesce(
    (select code from public.segments s
      where upper(trim(p)) = s.code
         or lower(trim(p)) = lower(s.name)
         or lower(trim(p)) = any (s.aliases)
      order by s.sort_order
      limit 1),
    p_default)
$$;

-- old free-text outcome -> standardized outcome
--   is_exact = the cell is just the phrase ("No response", "No thank you")
--   otherwise the phrase was found inside longer text (a pasted reply) and a person should confirm
create or replace function public.match_outcome(p_text text, out outcome_code text, out is_exact boolean, out phrase text)
language sql stable set search_path = public as $$
  select a.outcome_code,
         norm_text(regexp_replace(p_text, '[\s.!]+$', '')) = a.phrase,
         a.phrase
    from outcome_aliases a
   where norm_text(p_text) ~ ('\m' || regexp_replace(a.phrase, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '\M')
   order by length(a.phrase) desc
   limit 1
$$;


-- ---------------------------------------------------------------------
-- The import
-- ---------------------------------------------------------------------

create or replace function public.process_import_batch(p_batch_id bigint, p_run_automation boolean default true)
returns jsonb
language plpgsql set search_path = public, extensions as $$
declare
  b             import_batches;
  r             import_rows;
  v_seg         segments;
  v_email       text;
  v_domain      text;
  v_li          text;
  v_first       text;
  v_last        text;
  v_name_key    text;
  v_org_key     text;
  v_web_domain  text;
  v_state       char(2);
  v_sourced     date;
  v_contact_id  bigint;
  v_org_id      bigint;
  v_other_id    bigint;
  v_matched     text;
  v_result      text;
  v_detail      text;
  v_cand_org    bigint;
  v_cand_contact bigint;
  v_force_new   boolean;
  v_touch_on    date;
  v_touch_id    bigint;
  v_out         record;
  v_suggest     text;
  v_outcome     text;
  v_status      text;
  v_flags       text;
  v_summary     jsonb;
begin
  select * into b from import_batches where id = p_batch_id for update;
  if not found then raise exception 'Import batch % not found', p_batch_id; end if;
  if not p_run_automation then
    perform set_config('app.seeding', 'on', true);          -- history back-fill: no reminders for old rows
  end if;

  for r in
    select * from import_rows
     where batch_id = p_batch_id
       and (processed_at is null or (result = 'needs_review' and review_decision is not null))
     order by row_number, id
  loop
    begin   -- each row in its own sub-transaction: one bad row never stops the batch
      v_contact_id := null; v_org_id := null; v_matched := null; v_result := null; v_detail := null;
      v_cand_org := null; v_cand_contact := null; v_touch_id := null; v_flags := '';

      if r.review_decision = 'skip' then
        update import_rows set result = 'skipped', result_detail = 'Skipped after review', processed_at = now()
         where id = r.id;
        continue;
      end if;
      v_force_new := coalesce(r.review_decision = 'create_new', false);

      v_email      := norm_email(r.email);
      v_domain     := nullif(split_part(v_email, '@', 2), '');
      v_li         := norm_linkedin(r.linkedin);
      v_first      := coalesce(nullif(trim(r.first_name), ''), nullif(split_part(trim(coalesce(r.contact, '')), ' ', 1), ''));
      v_last       := coalesce(nullif(trim(r.last_name), ''),
                               nullif(trim(regexp_replace(trim(coalesce(r.contact, '')), '^\S+\s*', '')), ''));
      v_name_key   := norm_text(coalesce(v_first, '') || ' ' || coalesce(v_last, ''));
      v_org_key    := norm_org_name(r.org);
      v_web_domain := norm_domain(r.website);
      v_state      := resolve_state(r.state);
      v_sourced    := coalesce(parse_loose_date(r.date_added), local_date(b.created_at));
      select * into v_seg from segments where code = resolve_segment(r.segment, b.default_segment_code);
      if v_seg.code is null then
        raise exception 'No segment: fill the Segment column or set default_segment_code on the batch';
      end if;
      if v_email is null and v_li is null and v_name_key is null then
        update import_rows set result = 'skipped', result_detail = 'No name, email or LinkedIn on this row', processed_at = now()
         where id = r.id;
        continue;
      end if;

      -- 1) already in the CRM? (email, then LinkedIn, then a reviewer's decision)
      if v_email is not null then
        select id into v_contact_id from contacts where email_key = v_email;
        if found then v_matched := 'email'; end if;
      end if;
      if v_contact_id is null and v_li is not null then
        select id into v_contact_id from contacts where linkedin_key = v_li;
        if found then v_matched := 'LinkedIn'; end if;
      end if;
      if v_contact_id is null and r.review_decision = 'use_candidate' and r.review_candidate_contact_id is not null then
        v_contact_id := r.review_candidate_contact_id;
        v_matched := 'reviewer: same person';
        update contacts set notes = concat_ws(E'\n', notes, 'Also uses: ' || coalesce(v_email, trim(r.email)))
         where id = v_contact_id and v_email is not null;
      end if;

      -- the email points at one person and the LinkedIn at another
      if v_contact_id is not null and v_li is not null then
        select id into v_other_id from contacts where linkedin_key = v_li and id <> v_contact_id;
        if found then
          update import_rows
             set result = 'needs_review', matched_on = 'email and LinkedIn disagree',
                 review_candidate_contact_id = v_other_id, contact_id = v_contact_id,
                 result_detail = format('Email matches contact #%s but LinkedIn matches contact #%s. Possibly the same person entered twice.',
                                        v_contact_id, v_other_id),
                 processed_at = now()
           where id = r.id;
          continue;
        end if;
      end if;

      if v_contact_id is not null then
        -- fill blanks only, never overwrite what the team already has
        update contacts
           set phone                 = coalesce(phone, nullif(trim(r.phone), '')),
               linkedin_url          = coalesce(linkedin_url, nullif(trim(r.linkedin), '')),
               title                 = coalesce(title, nullif(trim(r.title), '')),
               linkedin_connected_on = coalesce(linkedin_connected_on, parse_yes_or_date(r.added_on_linkedin, v_sourced))
         where id = v_contact_id;
        v_result := 'existing_contact';
        select format('Already in the CRM (matched on %s): %s%s. %s%s',
                      v_matched, coalesce(c.full_name, c.email), coalesce(' at ' || o.name, ''),
                      coalesce('Last touch ' || to_char(lt.touched_at, 'Mon DD, YYYY') || ' via ' || tt.name || ': ' || oc.label,
                               'No outreach logged yet'),
                      case when c.do_not_contact then '. DO NOT CONTACT: ' || coalesce(c.dnc_reason, '') else '' end)
          into v_detail
          from contacts c
          left join organizations o on o.id = c.organization_id
          left join lateral (select t.touched_at, t.touch_type, t.outcome_code from touchpoints t
                              where t.contact_id = c.id order by t.touched_at desc limit 1) lt on true
          left join touch_types tt on tt.code = lt.touch_type
          left join outcomes oc on oc.code = lt.outcome_code
         where c.id = v_contact_id;
      else
        -- 2) a new person: is their organization already here?
        if v_seg.party_type = 'organization' then
          if r.review_decision = 'use_candidate' and r.review_candidate_org_id is not null then
            v_org_id := r.review_candidate_org_id; v_matched := 'reviewer: same organization';
          end if;
          if v_org_id is null and v_web_domain is not null then
            select id into v_org_id from organizations where domain = v_web_domain order by id limit 1;
            if found then v_matched := 'website'; end if;
          end if;
          if v_org_id is null and v_org_key is not null then
            select id into v_org_id from organizations where name_key = v_org_key
             order by (state is not distinct from v_state) desc, id limit 1;
            if found then v_matched := 'organization name'; end if;
          end if;
          if v_org_id is null and v_domain is not null
             and not exists (select 1 from freemail_domains f where f.domain = v_domain) then
            select organization_id into v_org_id from contacts
             where email_domain = v_domain and organization_id is not null
             group by organization_id order by count(*) desc limit 1;
            if found then v_matched := 'email domain'; end if;
          end if;
          -- close but not exact (typo, word order, "... Club"): a person decides
          if v_org_id is null and v_org_key is not null and not v_force_new then
            select id into v_cand_org
              from organizations
             where name_key % v_org_key
               and org_names_look_alike(name, r.org)
             order by similarity(name_key, v_org_key) desc
             limit 1;
            if v_cand_org is not null then
              update import_rows
                 set result = 'needs_review', matched_on = 'similar organization name',
                     review_candidate_org_id = v_cand_org,
                     result_detail = format('"%s" looks like existing organization "%s". Same organization?',
                                            trim(r.org), (select name from organizations where id = v_cand_org)),
                     processed_at = now()
               where id = r.id;
              continue;
            end if;
          end if;
        end if;

        -- 3) same (or nickname / typo) name already there under another email: a person decides
        if not v_force_new and v_name_key is not null then
          select id into v_cand_contact from contacts
           where person_names_look_alike(first_name, last_name, v_first, v_last)
             and (organization_id = v_org_id
                  or (v_org_id is null and organization_id is null and v_seg.party_type = 'individual'
                      and (v_state is null or state is null or state = v_state)))
           order by (name_key = v_name_key) desc, id
           limit 1;
          if found then
            update import_rows
               set result = 'needs_review', matched_on = 'same or similar name', review_candidate_contact_id = v_cand_contact,
                   organization_id = v_org_id,
                   result_detail = format('%s is already in the CRM with email %s. Same person with a new email?',
                                          (select full_name from contacts where id = v_cand_contact),
                                          coalesce((select email from contacts where id = v_cand_contact), '(none)')),
                   processed_at = now()
             where id = r.id;
            continue;
          end if;
        end if;

        -- what already happened at this organization (the "row 2500 vs row 600" hunt)
        if v_org_id is not null then
          select format('Organization already in the CRM (matched on %s). %s other %s there; last touch %s with %s: %s',
                        v_matched, count(distinct c.id), case when count(distinct c.id) = 1 then 'person' else 'people' end,
                        coalesce(to_char(max(t.touched_at), 'Mon DD, YYYY'), 'none'),
                        coalesce((array_agg(c2.full_name order by t.touched_at desc) filter (where t.id is not null))[1], 'nobody'),
                        coalesce((array_agg(oc.label order by t.touched_at desc) filter (where t.id is not null))[1], 'no outreach yet'))
            into v_detail
            from contacts c
            left join touchpoints t on t.contact_id = c.id
            left join contacts c2 on c2.id = t.contact_id
            left join outcomes oc on oc.code = t.outcome_code
           where c.organization_id = v_org_id;
          v_result := 'new_contact_existing_org';
        else
          v_result := 'new_contact';
          if v_seg.party_type = 'organization' and v_org_key is not null then
            insert into organizations (name, segment_code, website, state, reported_aum, owner_id, source_detail, legacy_ref)
            values (trim(r.org), v_seg.code, nullif(trim(r.website), ''), coalesce(v_state, b.default_state),
                    parse_amount(r.aum), b.owner_id, nullif(trim(r.source), ''),
                    b.label || ' / row ' || coalesce(r.row_number::text, '?'))
            returning id into v_org_id;
          end if;
          v_detail := 'Added';
        end if;

        insert into contacts (organization_id, segment_code, first_name, last_name, title, employer, email, phone,
                              linkedin_url, linkedin_connected_on, state, prospect_aum, source_channel_code,
                              source_detail, source_event_id, sourced_on, owner_id, notes, legacy_ref)
        values (v_org_id, v_seg.code, v_first, v_last, nullif(trim(r.title), ''),
                case when v_seg.party_type = 'individual' then nullif(trim(r.org), '') end,
                v_email, nullif(trim(r.phone), ''), nullif(trim(r.linkedin), ''),
                parse_yes_or_date(r.added_on_linkedin, v_sourced),
                coalesce(v_state, (select state from organizations where id = v_org_id), b.default_state),
                case when v_seg.party_type = 'individual' then parse_amount(r.aum) end,
                b.default_channel_code, nullif(trim(r.source), ''), b.event_id, v_sourced, b.owner_id,
                nullif(trim(r.notes), ''), b.label || ' / row ' || coalesce(r.row_number::text, '?'))
        returning id into v_contact_id;
        if v_email is null and nullif(trim(r.email), '') is not null then
          v_detail := v_detail || format('. Email "%s" is not valid and was left blank', trim(r.email));
        end if;
      end if;

      -- flags the rules raised on this person
      select concat_ws('. ',
               case when do_not_contact then 'FLAGGED DO NOT CONTACT: ' || coalesce(dnc_reason, '') end,
               case when is_university_affiliated then 'University contact: founder may know them' end)
        into v_flags
        from contacts where id = v_contact_id;
      if coalesce(v_flags, '') <> '' then v_detail := v_detail || '. ' || v_flags; end if;

      -- 4) the outreach columns become a touchpoint
      v_touch_on := parse_loose_date(r.date_outreached);
      if v_touch_on is not null then
        select * into v_out from match_outcome(r.outcome);
        v_suggest := case when exists (select 1 from outcomes o
                                        where o.code = v_out.outcome_code and b.default_touch_type = any (o.applies_to))
                          then v_out.outcome_code end;
        if nullif(trim(coalesce(r.outcome, '')), '') is null then          -- blank = still no response
          v_outcome := case when b.default_touch_type in ('email', 'check_in') then 'NO_RESPONSE' end;
          v_status  := 'confirmed';
        elsif v_suggest is not null and v_out.is_exact then               -- a clean label
          v_outcome := v_suggest; v_status := 'confirmed';
        elsif v_suggest is not null then                                  -- phrase inside a pasted reply
          v_outcome := v_suggest; v_status := 'needs_review';
        else                                                              -- could not tell
          v_outcome := case when b.default_touch_type in ('email', 'check_in') then 'NO_RESPONSE' end;
          v_status  := 'needs_review';
        end if;

        -- re-importing the same sheet does not create the touch twice
        select id into v_touch_id from touchpoints
         where contact_id = v_contact_id and touch_type = b.default_touch_type and local_date(touched_at) = v_touch_on
         limit 1;
        if v_touch_id is null then
          insert into touchpoints (contact_id, touch_type, direction, touched_at, campaign_id, event_id,
                                   outcome_code, outcome_status, outcome_raw,
                                   ai_suggested_outcome, ai_confidence, ai_reason, notes, owner_id)
          values (v_contact_id, b.default_touch_type,
                  case when b.default_touch_type = 'event' then 'in_person' else 'outbound' end,
                  (v_touch_on + time '09:00') at time zone 'America/Denver', b.campaign_id, b.event_id,
                  v_outcome, v_status, nullif(trim(r.outcome), ''),
                  case when v_status = 'needs_review' then v_suggest end,
                  case when v_status = 'needs_review' and v_suggest is not null then 0.6 end,
                  case when v_status = 'needs_review' and v_suggest is not null
                       then format('Matched "%s" in the old Outcome text', v_out.phrase)
                       when v_status = 'needs_review' then 'Could not match the old Outcome text' end,
                  nullif(trim(r.next_steps), ''), b.owner_id)
          returning id into v_touch_id;
        end if;
      end if;

      update import_rows
         set result = v_result, result_detail = v_detail, matched_on = v_matched,
             contact_id = v_contact_id,
             organization_id = (select organization_id from contacts where id = v_contact_id),
             touchpoint_id = v_touch_id, processed_at = now()
       where id = r.id;

    exception when others then
      update import_rows set result = 'error', result_detail = sqlerrm, processed_at = now() where id = r.id;
    end;
  end loop;

  select jsonb_build_object(
           'batch',                          b.label,
           'rows',                           count(*),
           'new_contacts',                   count(*) filter (where ir.result = 'new_contact'),
           'new_contacts_at_known_orgs',     count(*) filter (where ir.result = 'new_contact_existing_org'),
           'already_in_crm',                 count(*) filter (where ir.result = 'existing_contact'),
           'needs_review',                   count(*) filter (where ir.result = 'needs_review'),
           'skipped',                        count(*) filter (where ir.result = 'skipped'),
           'errors',                         count(*) filter (where ir.result = 'error'),
           'flagged_do_not_contact',         count(*) filter (where c.do_not_contact),
           'flagged_university',             count(*) filter (where c.is_university_affiliated),
           'outcomes_to_confirm',            count(*) filter (where t.outcome_status = 'needs_review'))
    into v_summary
    from import_rows ir
    left join contacts c    on c.id = ir.contact_id
    left join touchpoints t on t.id = ir.touchpoint_id
   where ir.batch_id = p_batch_id;

  update import_batches set status = 'processed', processed_at = now(), summary = v_summary where id = p_batch_id;
  return v_summary;
end $$;

-- ===================== 20260926000500_dashboard_views.sql =====================

-- =====================================================================
-- GAARD Capital CRM · Migration 5 of 6 · Views for the app and dashboard
--
-- Working lists (replace the tabs):
--   v_contacts              master list: sort / filter by anything
--   v_organizations         one row per org: who was contacted, rollover flag
--   v_reminders_due         the shared notifications tab
--   v_correspondence        every email / call / meeting, newest first
--   v_outcome_review_queue  suggested outcomes waiting for a click
--   v_newsletter_list       quarterly newsletter recipients
--   v_wrong_emails          the old "wrong email" tab
--   v_possible_duplicates   look-alike people and organizations
--   v_import_results        what process_import_batch() did with each row
-- Dashboard:
--   v_lead_funnel           one row per lead, milestone dates, one source channel
--   v_funnel_by_cohort      funnel counts by quarter / segment / state / channel
--   v_kpis_by_quarter       what happened each quarter (long format)
--   v_channel_performance   which introduction channel works best
--   v_event_performance     cost, people met, meetings, calls, AUM per event
--   v_cold_call_performance dials, connects, calls booked
--   v_pipeline              every opportunity with stage dates and AUM
--   v_aum_by_segment        funded vs onboarding by segment
--   v_funded_aum_by_quarter funded AUM over time
--   v_rfp_tracker           RFPs with deadlines
-- All views use security_invoker so Supabase row-level security applies.
-- =====================================================================

create or replace function public.quarter_label(p date) returns text
language sql immutable set search_path = '' as $$
  select case when p is null then null else to_char(p, 'YYYY') || '-Q' || to_char(p, 'Q') end
$$;


-- ---------------------------------------------------------------------
-- Working lists
-- ---------------------------------------------------------------------

create or replace view public.v_contacts with (security_invoker = true) as
select
  c.id                              as contact_id,
  c.full_name,
  c.first_name,
  c.last_name,
  c.title,
  c.organization_id,
  coalesce(o.name, c.employer)      as organization,
  sg.segment_group,
  sg.name                           as segment,
  c.segment_code,
  c.state,
  st.name                           as state_name,
  c.city,
  c.email,
  c.email_status,
  c.phone,
  c.linkedin_url,
  c.linkedin_connected_on,
  ch.name                           as source_channel,
  c.source_detail,
  ev.name                           as source_event,
  c.sourced_on,
  public.local_date(lt.touched_at)  as last_touch_on,
  ltt.name                          as last_touch_type,
  lo.label                          as last_outcome,
  public.local_date(ls.last_spoke_at) as last_spoke_on,
  nr.due_on                         as next_outreach_on,
  rt.label                          as next_action,
  coalesce(tc.touches, 0)           as touches,
  coalesce(tc.emails_sent, 0)       as emails_sent,
  coalesce(tc.calls_dialed, 0)      as calls_dialed,
  op.stage                          as pipeline_stage,
  op.expected_aum,
  op.funded_aum,
  coalesce(o.reported_aum, c.prospect_aum) as prospect_aum,
  c.is_decision_maker,
  c.is_university_affiliated,
  c.do_not_contact,
  c.dnc_reason,
  c.newsletter_status,
  c.follow_up_style,
  tm.full_name                      as owner,
  c.tags,
  c.notes,
  c.created_at
from public.contacts c
join public.segments sg            on sg.code = c.segment_code
left join public.organizations o   on o.id = c.organization_id
left join public.us_states st      on st.code = c.state
left join public.channels ch       on ch.code = c.source_channel_code
left join public.events ev         on ev.id = c.source_event_id
left join public.team_members tm   on tm.id = c.owner_id
left join lateral (
  select t.touched_at, t.touch_type, t.outcome_code
    from public.touchpoints t
   where t.contact_id = c.id
   order by t.touched_at desc, t.id desc
   limit 1) lt on true
left join public.touch_types ltt   on ltt.code = lt.touch_type
left join public.outcomes lo       on lo.code = lt.outcome_code
left join lateral (
  select max(coalesce(t.responded_at, t.touched_at)) as last_spoke_at
    from public.touchpoints t
    left join public.outcomes x on x.code = t.outcome_code
   where t.contact_id = c.id
     and (coalesce(x.counts_as_response, false) or t.touch_type = 'meeting')) ls on true
left join lateral (
  select r.due_on, r.reminder_type
    from public.reminders r
   where r.contact_id = c.id and r.status in ('open', 'snoozed')
   order by r.due_on
   limit 1) nr on true
left join public.reminder_types rt on rt.code = nr.reminder_type
left join lateral (
  select count(*)                                     as touches,
         count(*) filter (where t.touch_type = 'email') as emails_sent,
         count(*) filter (where t.touch_type = 'call')  as calls_dialed
    from public.touchpoints t
   where t.contact_id = c.id) tc on true
left join lateral (
  select p.stage, p.expected_aum, p.funded_aum
    from public.opportunities p
   where p.contact_id = c.id
      or (sg.party_type = 'organization' and c.organization_id is not null and p.organization_id = c.organization_id)
   order by (p.stage in ('funded', 'lost')), p.opened_on desc
   limit 1) op on true;


create or replace view public.v_organizations with (security_invoker = true) as
select
  o.id                              as organization_id,
  o.name,
  sg.segment_group,
  sg.name                           as segment,
  o.segment_code,
  o.org_type,
  o.state,
  o.city,
  o.website,
  o.reported_aum,
  o.employee_count,
  coalesce(cc.contacts, 0)          as contacts,
  coalesce(cc.decision_makers, 0)   as decision_makers,
  coalesce(tt.people_contacted, 0)  as people_contacted,
  coalesce(tt.touches, 0)           as touches,
  coalesce(tt.responses, 0)         as responses,
  tt.first_touch_on,
  tt.last_touch_on,
  tt.last_outcome,
  tt.last_contacted_person,
  op.stage                          as pipeline_stage,
  op.expected_aum,
  op.funded_aum,
  -- Jon's yearly rollover: nobody answered, so try someone else with leadership authority
  (coalesce(tt.touches, 0) >= 2 and coalesce(tt.responses, 0) = 0
     and tt.last_touch_on < public.local_today() - 90
     and op.stage is null and not o.do_not_contact) as rollover_suggested,
  o.is_university_affiliated,
  o.do_not_contact,
  o.dnc_reason,
  tm.full_name                      as owner,
  o.tags,
  o.notes
from public.organizations o
join public.segments sg          on sg.code = o.segment_code
left join public.team_members tm on tm.id = o.owner_id
left join lateral (
  select count(*) as contacts, count(*) filter (where c.is_decision_maker) as decision_makers
    from public.contacts c where c.organization_id = o.id) cc on true
left join lateral (
  select count(distinct t.contact_id)                                    as people_contacted,
         count(*)                                                        as touches,
         count(*) filter (where x.counts_as_response)                    as responses,
         min(public.local_date(t.touched_at))                            as first_touch_on,
         max(public.local_date(t.touched_at))                            as last_touch_on,
         (array_agg(x.label order by t.touched_at desc))[1]              as last_outcome,
         (array_agg(c.full_name order by t.touched_at desc))[1]          as last_contacted_person
    from public.touchpoints t
    join public.contacts c on c.id = t.contact_id
    left join public.outcomes x on x.code = t.outcome_code
   where c.organization_id = o.id) tt on true
left join lateral (
  select p.stage, p.expected_aum, p.funded_aum
    from public.opportunities p
   where p.organization_id = o.id
   order by (p.stage in ('funded', 'lost')), p.opened_on desc
   limit 1) op on true;


create or replace view public.v_reminders_due with (security_invoker = true) as
select
  r.id                              as reminder_id,
  r.reminder_type,
  rt.label                          as reminder_label,
  r.title,
  r.details,
  r.due_on,
  case when r.due_on <  public.local_today()     then 'overdue'
       when r.due_on =  public.local_today()     then 'today'
       when r.due_on <= public.local_today() + 7 then 'this_week'
       else 'later' end             as due_bucket,
  greatest(public.local_today() - r.due_on, 0) as days_overdue,
  r.status,
  r.follow_up_style,
  r.contact_id,
  c.full_name,
  c.email,
  c.phone,
  coalesce(c.state, o.state)        as state,
  coalesce(o.name, c.employer)      as organization,
  sg.name                           as segment,
  lo.label                          as last_outcome,
  public.local_date(lt.touched_at)  as last_touch_on,
  tm.full_name                      as assigned_to,
  r.opportunity_id,
  r.rfp_id,
  r.created_by,
  r.created_at
from public.reminders r
join public.reminder_types rt      on rt.code = r.reminder_type
left join public.contacts c        on c.id = r.contact_id
left join public.organizations o   on o.id = coalesce(r.organization_id, c.organization_id)
left join public.segments sg       on sg.code = coalesce(c.segment_code, o.segment_code)
left join public.team_members tm   on tm.id = r.assigned_to
left join lateral (
  select t.touched_at, t.outcome_code from public.touchpoints t
   where t.contact_id = r.contact_id order by t.touched_at desc limit 1) lt on true
left join public.outcomes lo       on lo.code = lt.outcome_code
where r.status in ('open', 'snoozed');


-- the correspondence column, rebuilt: newest first per contact
-- (order by occurred_at desc when querying)
create or replace view public.v_correspondence with (security_invoker = true) as
select
  e.contact_id,
  e.sent_at                         as occurred_at,
  case e.direction when 'inbound' then 'Email received' else 'Email sent' end as kind,
  e.subject                         as headline,
  e.body_text                       as body,
  e.from_email                      as who,
  e.touchpoint_id,
  'email'                           as source
from public.email_messages e
union all
select
  t.contact_id,
  coalesce(t.responded_at, t.touched_at),
  tt.name,
  coalesce(t.subject, x.label),
  coalesce(t.notes, t.response_excerpt),
  tm.full_name,
  t.id,
  'touchpoint'
from public.touchpoints t
join public.touch_types tt       on tt.code = t.touch_type
left join public.outcomes x      on x.code = t.outcome_code
left join public.team_members tm on tm.id = t.owner_id
where not exists (select 1 from public.email_messages e where e.touchpoint_id = t.id);


create or replace view public.v_outcome_review_queue with (security_invoker = true) as
select
  t.id                              as touchpoint_id,
  t.contact_id,
  c.full_name,
  coalesce(o.name, c.employer)      as organization,
  tt.name                           as touch_type,
  public.local_date(t.touched_at)   as touched_on,
  t.responded_at,
  cur.label                         as provisional_outcome,
  sug.label                         as suggested_outcome,
  t.ai_suggested_outcome,
  t.ai_confidence,
  t.ai_reason,
  t.response_excerpt,
  t.outcome_raw,
  (select e.body_text from public.email_messages e
    where e.touchpoint_id = t.id and e.direction = 'inbound'
    order by e.sent_at desc limit 1) as latest_reply
from public.touchpoints t
join public.contacts c          on c.id = t.contact_id
join public.touch_types tt      on tt.code = t.touch_type
left join public.organizations o on o.id = c.organization_id
left join public.outcomes cur   on cur.code = t.outcome_code
left join public.outcomes sug   on sug.code = t.ai_suggested_outcome
where t.outcome_status = 'needs_review';


create or replace view public.v_newsletter_list with (security_invoker = true) as
select c.id as contact_id, c.full_name, c.email, coalesce(o.name, c.employer) as organization,
       sg.segment_group, sg.name as segment, c.state, c.newsletter_added_on, c.newsletter_added_via
  from public.contacts c
  join public.segments sg on sg.code = c.segment_code
  left join public.organizations o on o.id = c.organization_id
 where c.newsletter_status = 'subscribed'
   and not c.do_not_contact
   and c.email_key is not null
   and c.email_status not in ('bounced', 'wrong_person');


create or replace view public.v_wrong_emails with (security_invoker = true) as
select c.id as contact_id, c.full_name, coalesce(o.name, c.employer) as organization, c.email, c.email_status,
       c.phone, c.linkedin_url, c.state,
       (select max(public.local_date(t.touched_at)) from public.touchpoints t
         where t.contact_id = c.id and t.outcome_code in ('BOUNCED', 'WRONG_PERSON')) as flagged_on,
       (select min(r.due_on) from public.reminders r
         where r.contact_id = c.id and r.status in ('open', 'snoozed')
           and r.reminder_type in ('fix_contact_info', 'find_new_contact')) as fix_due_on
  from public.contacts c
  left join public.organizations o on o.id = c.organization_id
 where c.email_status in ('bounced', 'wrong_person');


create or replace view public.v_possible_duplicates with (security_invoker = true) as
-- people at the same organization with the same name, a nickname or a typo
select 'contact'::text as entity, a.id as id_a, b.id as id_b, a.full_name as name_a, b.full_name as name_b,
       a.email as detail_a, b.email as detail_b,
       case when a.name_key = b.name_key then 'Same name at the same organization'
            else 'Similar name at the same organization' end as reason
  from public.contacts a
  join public.contacts b on a.id < b.id and a.organization_id = b.organization_id
 where public.person_names_look_alike(a.first_name, a.last_name, b.first_name, b.last_name)
union all
-- individuals (no organization) with look-alike names in the same state
select 'contact', a.id, b.id, a.full_name, b.full_name, a.email, b.email,
       'Similar name (individuals, same state)'
  from public.contacts a
  join public.contacts b on a.id < b.id
                        and a.organization_id is null and b.organization_id is null
                        and a.state is not distinct from b.state
                        and public.norm_text(a.last_name) = public.norm_text(b.last_name)
 where public.person_names_look_alike(a.first_name, a.last_name, b.first_name, b.last_name)
union all
-- organizations with the same website, or a look-alike name (typo, word order, extra generic word)
select 'organization', a.id, b.id, a.name, b.name,
       coalesce(a.domain, a.state), coalesce(b.domain, b.state),
       case when a.domain = b.domain then 'Same website' else 'Look-alike name' end
  from public.organizations a
  join public.organizations b on a.id < b.id
                             and (a.domain = b.domain or a.name_key operator(extensions.%) b.name_key)
 where a.domain = b.domain or public.org_names_look_alike(a.name, b.name);


create or replace view public.v_import_results with (security_invoker = true) as
select b.id as batch_id, b.label as batch, b.status as batch_status, ir.row_number, ir.result, ir.result_detail,
       ir.matched_on, ir.contact, ir.first_name, ir.email, ir.org, ir.source, ir.date_outreached, ir.outcome,
       ir.contact_id, ir.organization_id, ir.touchpoint_id,
       ir.review_candidate_contact_id, ir.review_candidate_org_id, ir.review_decision, ir.id as import_row_id
  from public.import_rows ir
  join public.import_batches b on b.id = ir.batch_id;


-- ---------------------------------------------------------------------
-- Dashboard
-- ---------------------------------------------------------------------

-- One row per lead (a person we reached out to, or who has an opportunity).
-- Each lead has exactly one source channel, so nothing is counted twice.
-- Reaching a later stage implies the earlier ones (funded => onboarded => hot => call).
create or replace view public.v_lead_funnel with (security_invoker = true) as
select
  c.id                                         as contact_id,
  c.full_name,
  c.organization_id,
  coalesce(o.name, c.employer)                 as organization,
  c.segment_code,
  sg.segment_group,
  sg.name                                      as segment,
  sg.sort_order                                as segment_sort,
  c.state,
  coalesce(op.source_channel_code, c.source_channel_code, ft.first_channel) as source_channel_code,
  ch.name                                      as source_channel,
  c.source_event_id,
  ft.first_outreach_on,
  public.quarter_label(coalesce(ft.first_outreach_on, op.opened_on)) as cohort_quarter,
  coalesce(fr.first_response_on, op.opened_on) as responded_on,
  op.opened_on                                 as call_booked_on,
  op.first_call_on,
  coalesce(op.hot_on, op.onboarding_started_on, op.funded_on) as hot_on,
  coalesce(op.onboarding_started_on, op.funded_on)            as onboarding_on,
  op.funded_on,
  op.expected_aum,
  op.funded_aum,
  op.stage                                     as current_stage,
  op.id                                        as opportunity_id,
  op.converting_channel_code,
  c.is_university_affiliated
from public.contacts c
join public.segments sg          on sg.code = c.segment_code
left join public.organizations o on o.id = c.organization_id
left join lateral (
  select min(public.local_date(t.touched_at))                  as first_outreach_on,
         (array_agg(tt.channel_code order by t.touched_at))[1]  as first_channel
    from public.touchpoints t
    join public.touch_types tt on tt.code = t.touch_type and tt.is_outreach
   where t.contact_id = c.id) ft on true
left join lateral (
  select min(public.local_date(coalesce(t.responded_at, t.touched_at))) as first_response_on
    from public.touchpoints t
    join public.outcomes x on x.code = t.outcome_code and x.counts_as_response
   where t.contact_id = c.id) fr on true
left join lateral (
  select p.* from public.opportunities p
   where p.contact_id = c.id
   order by p.opened_on
   limit 1) op on true
left join public.channels ch on ch.code = coalesce(op.source_channel_code, c.source_channel_code, ft.first_channel)
where ft.first_outreach_on is not null or op.id is not null;


create or replace view public.v_funnel_by_cohort with (security_invoker = true) as
select
  cohort_quarter,
  segment_group,
  segment,
  state,
  source_channel,
  count(*)                    as leads,
  count(responded_on)         as responded,
  count(call_booked_on)       as calls,
  count(hot_on)               as hot,
  count(onboarding_on)        as onboarding,
  count(funded_on)            as funded,
  coalesce(sum(funded_aum), 0) as funded_aum
from public.v_lead_funnel
group by cohort_quarter, segment_group, segment, state, source_channel;


-- What happened in each quarter, one row per (quarter, segment, state, channel, metric).
-- Outreach metrics use the channel of the touch; pipeline metrics use the lead's source channel.
create or replace view public.v_kpis_by_quarter with (security_invoker = true) as
with facts as (
  -- outreach activity
  select public.local_date(t.touched_at) as on_date, c.segment_code, c.state, tt.channel_code,
         case t.touch_type when 'email' then 'emails_sent' when 'call' then 'calls_dialed'
                           when 'event' then 'people_met_at_events' when 'intro' then 'referral_intros'
                           when 'rfp' then 'rfp_updates' end as metric,
         1::numeric as value
    from public.touchpoints t
    join public.contacts c     on c.id = t.contact_id
    join public.touch_types tt on tt.code = t.touch_type and tt.is_outreach
  union all
  select public.local_date(t.touched_at), c.segment_code, c.state, 'COLD_CALL', 'calls_connected', 1
    from public.touchpoints t join public.contacts c on c.id = t.contact_id
   where t.touch_type = 'call' and t.outcome_code not in ('NO_ANSWER', 'VOICEMAIL', 'WRONG_NUMBER')
  union all
  -- replies (a person answered), dated when they answered
  select public.local_date(coalesce(t.responded_at, t.touched_at)), c.segment_code, c.state, tt.channel_code,
         case when x.sentiment = 'positive' then 'positive_responses' else 'other_responses' end, 1
    from public.touchpoints t
    join public.contacts c     on c.id = t.contact_id
    join public.touch_types tt on tt.code = t.touch_type and tt.is_outreach
    join public.outcomes x     on x.code = t.outcome_code and x.counts_as_response
  union all
  select public.local_date(t.touched_at), c.segment_code, c.state, null, 'meetings_held', 1
    from public.touchpoints t join public.contacts c on c.id = t.contact_id
   where t.touch_type = 'meeting'
  union all
  select p.first_call_on, p.segment_code, p.state, p.source_channel_code, 'first_calls_held', 1
    from public.opportunities p where p.first_call_on is not null
  union all
  -- new prospects added
  select c.sourced_on, c.segment_code, c.state, c.source_channel_code, 'new_prospects', 1
    from public.contacts c where c.sourced_on is not null
  union all
  -- pipeline milestones, credited to the lead's source channel
  select p.opened_on, p.segment_code, p.state, p.source_channel_code, 'calls_booked', 1
    from public.opportunities p
  union all
  select p.onboarding_started_on, p.segment_code, p.state, p.source_channel_code, 'onboarding_started', 1
    from public.opportunities p where p.onboarding_started_on is not null
  union all
  select p.funded_on, p.segment_code, p.state, p.source_channel_code, 'funded_accounts', 1
    from public.opportunities p where p.funded_on is not null
  union all
  select p.funded_on, p.segment_code, p.state, p.source_channel_code, 'funded_aum', p.funded_aum
    from public.opportunities p where p.funded_on is not null
  union all
  select e.start_on, e.target_segment_code, e.state, 'EVENT', 'event_spend', e.cost_usd
    from public.events e
)
select public.quarter_label(f.on_date) as quarter,
       f.segment_code, sg.segment_group, sg.name as segment,
       f.state, f.channel_code, ch.name as channel,
       f.metric,
       sum(f.value) as value
  from facts f
  left join public.segments sg on sg.code = f.segment_code
  left join public.channels ch on ch.code = f.channel_code
 where f.on_date is not null and f.on_date <= public.local_today()
 group by 1, 2, 3, 4, 5, 6, 7, 8;


-- Which introduction channel works best (each lead counted once, under its source channel)
create or replace view public.v_channel_performance with (security_invoker = true) as
select
  ch.code                                       as channel_code,
  ch.name                                       as channel,
  count(f.contact_id)                           as leads,
  count(f.responded_on)                         as responded,
  count(f.call_booked_on)                       as calls,
  count(f.hot_on)                               as hot,
  count(f.onboarding_on)                        as onboarding,
  count(f.funded_on)                            as funded,
  coalesce(sum(f.funded_aum), 0)                as funded_aum,
  round(count(f.responded_on)::numeric   / nullif(count(f.contact_id), 0), 4)     as response_rate,
  round(count(f.call_booked_on)::numeric / nullif(count(f.contact_id), 0), 4)     as lead_to_call_rate,
  round(count(f.funded_on)::numeric      / nullif(count(f.call_booked_on), 0), 4) as call_to_funded_rate
from public.channels ch
left join public.v_lead_funnel f on f.source_channel_code = ch.code
group by ch.code, ch.name, ch.sort_order
order by ch.sort_order;


create or replace view public.v_event_performance with (security_invoker = true) as
select
  e.id                                  as event_id,
  e.name,
  e.event_type,
  e.format,
  e.hosted_by_us,
  e.host_org,
  e.start_on,
  public.quarter_label(e.start_on)      as quarter,
  e.city,
  e.state,
  sg.name                               as target_segment,
  e.cost_usd,
  coalesce(m.people_met, 0)             as people_met,
  coalesce(m.meetings_at_event, 0)      as meetings_at_event,
  coalesce(n.new_contacts, 0)           as new_contacts,
  coalesce(f.responded, 0)              as responded,
  coalesce(f.calls, 0)                  as calls,
  coalesce(f.onboarding, 0)             as onboarding,
  coalesce(f.funded, 0)                 as funded,
  coalesce(f.funded_aum, 0)             as funded_aum,
  round(e.cost_usd / nullif(m.people_met, 0), 2) as cost_per_person_met,
  round(e.cost_usd / nullif(f.calls, 0), 2)      as cost_per_call
from public.events e
left join public.segments sg on sg.code = e.target_segment_code
left join lateral (
  select count(distinct t.contact_id) as people_met,
         count(*) filter (where t.outcome_code in ('MEETING_AT_EVENT', 'INTERESTED')) as meetings_at_event
    from public.touchpoints t
   where t.event_id = e.id and t.touch_type = 'event') m on true
left join lateral (
  select count(*) as new_contacts from public.contacts c where c.source_event_id = e.id) n on true
left join lateral (
  select count(lf.responded_on) as responded, count(lf.call_booked_on) as calls,
         count(lf.onboarding_on) as onboarding, count(lf.funded_on) as funded,
         coalesce(sum(lf.funded_aum), 0) as funded_aum
    from public.v_lead_funnel lf
   where lf.source_event_id = e.id) f on true;


create or replace view public.v_cold_call_performance with (security_invoker = true) as
select
  coalesce(cp.name, '(no campaign)')  as campaign,
  sg.segment_group,
  sg.name                             as segment,
  c.state,
  count(*)                            as dials,
  count(distinct t.contact_id)        as people_called,
  round(count(*)::numeric / nullif(count(distinct t.contact_id), 0), 2) as dials_per_person,
  count(*) filter (where t.outcome_code not in ('NO_ANSWER', 'VOICEMAIL', 'WRONG_NUMBER')) as connects,
  count(*) filter (where t.outcome_code = 'VOICEMAIL')    as voicemails,
  count(*) filter (where t.outcome_code = 'WRONG_NUMBER') as wrong_numbers,
  count(*) filter (where t.outcome_code = 'INTERESTED')   as calls_booked,
  round(count(*) filter (where t.outcome_code not in ('NO_ANSWER', 'VOICEMAIL', 'WRONG_NUMBER'))::numeric
        / nullif(count(*), 0), 4)     as connect_rate
from public.touchpoints t
join public.contacts c        on c.id = t.contact_id
join public.segments sg       on sg.code = c.segment_code
left join public.campaigns cp on cp.id = t.campaign_id
where t.touch_type = 'call'
group by 1, 2, 3, 4;


create or replace view public.v_pipeline with (security_invoker = true) as
select
  op.id                             as opportunity_id,
  op.stage,
  ps.label                          as stage_label,
  ps.sort_order                     as stage_sort,
  op.contact_id,
  c.full_name                       as contact,
  op.organization_id,
  coalesce(o.name, c.employer)      as organization,
  sg.segment_group,
  sg.name                           as segment,
  op.state,
  sch.name                          as source_channel,
  cch.name                          as converted_by,
  ev.name                           as source_event,
  rf.title                          as rfp,
  op.opened_on,
  op.first_call_on,
  op.hot_on,
  op.onboarding_started_on,
  op.contract_signed_on,
  op.funded_on,
  op.closed_on,
  op.lost_reason,
  op.expected_aum,
  op.funded_aum,
  case when not ps.is_closed then public.local_today()
       - coalesce(op.onboarding_started_on, op.hot_on, op.first_call_on, op.opened_on) end as days_in_stage,
  lt.last_touch_on,
  nr.next_step_on,
  tm.full_name                      as owner
from public.opportunities op
join public.pipeline_stages ps     on ps.code = op.stage
join public.contacts c             on c.id = op.contact_id
join public.segments sg            on sg.code = op.segment_code
left join public.organizations o   on o.id = op.organization_id
left join public.channels sch      on sch.code = op.source_channel_code
left join public.channels cch      on cch.code = op.converting_channel_code
left join public.events ev         on ev.id = op.source_event_id
left join public.rfps rf           on rf.id = op.rfp_id
left join public.team_members tm   on tm.id = op.owner_id
left join lateral (
  select max(public.local_date(t.touched_at)) as last_touch_on from public.touchpoints t
   where t.contact_id = op.contact_id
      or (op.organization_id is not null and t.organization_id = op.organization_id)) lt on true
left join lateral (
  select min(r.due_on) as next_step_on from public.reminders r
   where r.status in ('open', 'snoozed') and (r.opportunity_id = op.id or r.contact_id = op.contact_id)) nr on true;


-- "separate clients who are already onboarded and clients who are onboarding, by business type"
create or replace view public.v_aum_by_segment with (security_invoker = true) as
select
  sg.segment_group,
  sg.name                                                              as segment,
  sg.code                                                              as segment_code,
  count(op.id) filter (where op.stage = 'funded')                      as funded_clients,
  coalesce(sum(op.funded_aum) filter (where op.stage = 'funded'), 0)   as funded_aum,
  count(op.id) filter (where op.stage = 'onboarding')                  as onboarding_clients,
  coalesce(sum(op.expected_aum) filter (where op.stage = 'onboarding'), 0) as onboarding_expected_aum,
  count(op.id) filter (where op.stage in ('call', 'hot'))              as early_pipeline,
  coalesce(sum(op.expected_aum) filter (where op.stage in ('call', 'hot')), 0) as early_pipeline_expected_aum
from public.segments sg
left join public.opportunities op on op.segment_code = sg.code
group by sg.segment_group, sg.name, sg.code, sg.sort_order
order by sg.sort_order;


create or replace view public.v_funded_aum_by_quarter with (security_invoker = true) as
select public.quarter_label(op.funded_on) as quarter, sg.segment_group, sg.name as segment, op.state,
       sch.name as source_channel, count(*) as funded_accounts, sum(op.funded_aum) as funded_aum
  from public.opportunities op
  join public.segments sg      on sg.code = op.segment_code
  left join public.channels sch on sch.code = op.source_channel_code
 where op.funded_on is not null
 group by 1, 2, 3, 4, 5;


create or replace view public.v_rfp_tracker with (security_invoker = true) as
select
  r.id                              as rfp_id,
  r.title,
  o.name                            as organization,
  sg.name                           as segment,
  o.state,
  c.full_name                       as contact,
  r.mandate_type,
  r.found_via,
  r.est_mandate_aum,
  r.status,
  r.released_on,
  r.questions_due_on,
  r.due_on,
  case when r.status in ('identified', 'intent_to_bid') then r.due_on - public.local_today() end as days_until_due,
  r.submitted_on,
  r.decision_on,
  op.stage                          as pipeline_stage,
  op.funded_aum,
  tm.full_name                      as owner,
  r.notes
from public.rfps r
join public.organizations o       on o.id = r.organization_id
join public.segments sg           on sg.code = o.segment_code
left join public.contacts c       on c.id = r.contact_id
left join public.team_members tm  on tm.id = r.owner_id
left join lateral (
  select p.stage, p.funded_aum from public.opportunities p where p.rfp_id = r.id
   order by p.opened_on desc limit 1) op on true;

-- ===================== 20260926000600_access_control.sql =====================

-- =====================================================================
-- GAARD Capital CRM · Migration 6 of 6 · Access control (Supabase)
--
-- Jon: "everyone on the team right now has access to this ... it's not
-- really a concern about limiting access". So the rule is simple:
-- a signed-in person who is an active row in team_members can read and
-- edit everything; nobody else can see anything.
--
-- After running this:
--   1. Supabase dashboard > Authentication > turn OFF public sign-ups,
--      invite each team member by email.
--   2. Put each person's auth user id in team_members.auth_user_id.
--
-- On a plain Postgres without Supabase's auth schema this migration
-- only enables row-level security and skips the policies.
-- =====================================================================

do $migration$
declare
  t record;
  has_auth boolean := to_regprocedure('auth.uid()') is not null
                      and exists (select 1 from pg_roles where rolname = 'authenticated');
begin
  if has_auth then
    execute $f$
      create or replace function public.is_team_member() returns boolean
      language sql stable security definer set search_path = '' as $body$
        select exists (select 1 from public.team_members
                        where auth_user_id = auth.uid() and is_active)
      $body$
    $f$;
    execute 'revoke execute on function public.is_team_member() from public, anon';
    execute 'grant execute on function public.is_team_member() to authenticated';
  else
    raise notice 'Supabase auth not found: enabling row-level security without policies';
  end if;

  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t.tablename);
    if has_auth then
      execute format('drop policy if exists team_access on public.%I', t.tablename);
      execute format('create policy team_access on public.%I for all to authenticated '
                     'using (public.is_team_member()) with check (public.is_team_member())', t.tablename);
    end if;
  end loop;
end
$migration$;

-- ===================== 20261003000100_workbook_import.sql =====================

-- =====================================================================
-- GAARD Capital CRM · Migration 7 of 9 · Jon's workbook: tab profiles and the extra columns
--
-- The real outreach workbook has ten tabs, each with its own column set, and
-- the Sep 26 import pipeline only knew the outreach-sheet columns. This
-- migration teaches it the rest:
--
-- 1. import_header_aliases    every header Jon uses -> one field name
-- 2. import_tab_profiles      one row per tab: segment, channel, touch type,
--                             default outcome, follow-up days, tags, header map
-- 3. import_batches/import_rows carry those defaults, plus an `extra` jsonb
--    for columns the outreach sheet never had (city, org type, status,
--    plans served, loyalty dates ...)
-- 4. organizations / contacts get the matching columns (mailing address,
--    activity status, plans served, commissions, "reach out again?" ...)
-- 5. import_uploaded_table()  CSV table uploaded in the dashboard -> a batch
--    import_gaard_tab()       the same, driven by a tab profile
--    check_upload_headers()   says which headers it did not recognise
-- 6. history_load()           a back-fill flag: facts are recorded, but the
--    do-not-contact block and reminder superseding stand down for old rows
-- 7. process_import_batch()   rewritten to use all of the above: name-only
--    matching for tabs with no email column, the Onboarded tab -> the
--    opportunity, the Customer Loyalty tab -> card / check-in reminders
--
-- First run in the Supabase SQL Editor on Oct 3, 2026; this file was
-- rebuilt from the live schema on Oct 14, 2026.
-- =====================================================================

-- ---------------------------------------------------------------------
-- 1. Columns the workbook needs
-- ---------------------------------------------------------------------
alter table public.channels
  add column if not exists aliases text[] not null default '{}';

alter table public.contacts
  add column if not exists activity_status text,
  add column if not exists mailing_address text;
do $$ begin
  alter table public.contacts
    add constraint contacts_activity_status_check check (activity_status in ('active', 'dormant'));
exception when duplicate_object then null; end $$;
COMMENT ON COLUMN public.contacts.activity_status IS 'Next Step / Individuals tabs "Active/Dorm": active = still being worked, dormant = parked';

alter table public.organizations
  add column if not exists plans_served          integer,
  add column if not exists commissions           numeric(14,2),
  add column if not exists shared_employers      text,
  add column if not exists advertises_retirement boolean,
  add column if not exists reach_out_again       boolean,
  add column if not exists no_reach_out_reason   text,
  add column if not exists mailing_address       text;
COMMENT ON COLUMN public.organizations.org_type IS 'Sub-type: human services, community foundation, Benefit group ...; service line for an affiliate (Affiliates: "Services"); industry for a small business';
COMMENT ON COLUMN public.organizations.reported_aum IS 'AUM from sourcing (Form 990, website, research); plan assets for a 401(k) prospect (Small Biz: "PlanAssets")';
COMMENT ON COLUMN public.organizations.employee_count IS 'Headcount, or plan participants for a 401(k) prospect (Small Biz: "Participants")';
COMMENT ON COLUMN public.organizations.reach_out_again IS 'Master list "Reach Out Again?": false = do not re-source this organization next year (not the same as do-not-contact)';

alter table public.import_batches
  add column if not exists default_org_type        text,
  add column if not exists default_outcome_code    text references public.outcomes(code),
  add column if not exists default_follow_up_days  integer,
  add column if not exists tags                    text[]  not null default '{}',
  add column if not exists match_by_name           boolean not null default false,
  add column if not exists header_map              jsonb   not null default '{}',
  add column if not exists history_load            boolean not null default true;

alter table public.import_rows
  add column if not exists follow_up_on text,
  add column if not exists extra_notes  text,
  add column if not exists extra        jsonb not null default '{}';

-- ---------------------------------------------------------------------
-- 2. Header aliases and tab profiles
-- ---------------------------------------------------------------------
create table if not exists public.import_header_aliases (
    header_key text not null,
    field text not null,                 -- the import_rows column (or extra ->> key) this header feeds
    constraint import_header_aliases_field_check check ((field = any (array['date_added'::text, 'source'::text, 'contact'::text, 'first_name'::text, 'last_name'::text, 'title'::text, 'email'::text, 'org'::text, 'website'::text, 'linkedin'::text, 'added_on_linkedin'::text, 'phone'::text, 'aum'::text, 'state'::text, 'segment'::text, 'notes'::text, 'date_outreached'::text, 'outcome'::text, 'next_steps'::text, 'follow_up_on'::text, 'extra_notes'::text, 'city'::text, 'org_type'::text, 'channel'::text, 'status'::text, 'response_notes'::text, 'activity_status'::text, 'newsletter'::text, 'mailing_address'::text, 'reach_out_again'::text, 'no_reach_out_reason'::text, 'plans_served'::text, 'commissions'::text, 'shared_employers'::text, 'advertises_retirement'::text, 'employee_count'::text, 'onboarding_sent_on'::text, 'funded_on'::text, 'outcome_2'::text, 'loyalty_thanksgiving'::text, 'loyalty_referral_1'::text, 'loyalty_referral_2'::text, 'loyalty_referral_3'::text, 'date_source_approved'::text, 'new_contact'::text, 'new_first_name'::text, 'new_email'::text, 'new_org'::text, 'new_website'::text, 'new_linkedin'::text, 'new_notes'::text, 'campaign'::text, 'ignore'::text])))
);
alter table public.import_header_aliases add constraint import_header_aliases_pkey primary key (header_key);
comment on table public.import_header_aliases is 'Every column header Jon''s tabs use, normalised, -> the field it feeds. ''ignore'' drops the column.';

create table if not exists public.import_tab_profiles (
    tab text not null,
    description text,
    segment text,
    channel_code text default 'COLD_EMAIL'::text not null,
    touch_type text default 'email'::text not null,
    org_type text,
    default_outcome_code text,
    follow_up_days integer,
    tags text[] default '{}'::text[] not null,
    match_by_name boolean default false not null,
    header_map jsonb default '{}'::jsonb not null,
    prep_notes text,
    sort_order integer default 0 not null
);
alter table public.import_tab_profiles add constraint import_tab_profiles_pkey primary key (tab);
alter table public.import_tab_profiles
  add constraint import_tab_profiles_channel_code_fkey foreign key (channel_code) references public.channels(code),
  add constraint import_tab_profiles_default_outcome_code_fkey foreign key (default_outcome_code) references public.outcomes(code),
  add constraint import_tab_profiles_touch_type_fkey foreign key (touch_type) references public.touch_types(code);
comment on table public.import_tab_profiles is 'One row per workbook tab: how import_gaard_tab() should read it. The rows are in migration 10.';

-- same access rule as every other table (migration 6)
do $$
declare t text;
begin
  foreach t in array array['import_header_aliases', 'import_tab_profiles'] loop
    execute format('alter table public.%I enable row level security', t);
    if to_regprocedure('public.is_team_member()') is not null then
      execute format('drop policy if exists team_access on public.%I', t);
      execute format('create policy team_access on public.%I for all to authenticated '
                     'using (public.is_team_member()) with check (public.is_team_member())', t);
    end if;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 3. Helpers
-- ---------------------------------------------------------------------
create or replace function public.history_load() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(current_setting('app.history_load', true), 'off') = 'on'
$$;

create or replace function public.parse_yes_no(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when lower(trim(coalesce(p, ''))) in ('yes', 'y', 'true', 't', 'x', '1', '✓', '✔') then true
    when lower(trim(coalesce(p, ''))) in ('no', 'n', 'false', 'f', '0')                then false
    when lower(trim(coalesce(p, ''))) ~ '^yes\M'                                       then true
    when lower(trim(coalesce(p, ''))) ~ '^no\M'                                        then false
    else null end
$$;

create or replace function public.resolve_channel(p text, p_default text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce(
    (select c.code from public.channels c
      where upper(trim(p)) = c.code or lower(trim(p)) = lower(c.name) or lower(trim(p)) = any (c.aliases)
      order by c.sort_order limit 1),
    (select c.code from public.channels c, unnest(c.aliases) a
      where lower(trim(coalesce(p, ''))) like '%' || a || '%'
      order by length(a) desc, c.sort_order limit 1),
    p_default)
$$;

create or replace function public.resolve_header(p_header text, p_header_map jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select value from jsonb_each_text(coalesce(p_header_map, '{}'))
      where regexp_replace(lower(key), '[^a-z0-9]', '', 'g') = regexp_replace(lower(p_header), '[^a-z0-9]', '', 'g')
      limit 1),
    (select field from import_header_aliases
      where header_key = regexp_replace(lower(p_header), '[^a-z0-9]', '', 'g')))
$$;

create or replace function public.check_upload_headers(p_table regclass, p_tab text DEFAULT NULL::text) RETURNS TABLE(column_name text, maps_to text, filled_rows bigint, note text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
declare
  v_map  jsonb := '{}';
  a      record;
  v_n    bigint;
begin
  if p_tab is not null then
    select header_map into v_map from import_tab_profiles where lower(tab) = lower(p_tab);
    if not found then
      raise exception 'Unknown tab "%". Known tabs: %', p_tab,
        (select string_agg(tab, ', ' order by sort_order) from import_tab_profiles);
    end if;
  end if;
  for a in
    select attname from pg_attribute
     where attrelid = p_table and attnum > 0 and not attisdropped
     order by attnum
  loop
    execute format('select count(*) from %s where nullif(btrim(%I::text), '''') is not null', p_table, a.attname) into v_n;
    column_name := a.attname;
    maps_to     := resolve_header(a.attname, v_map);
    filled_rows := v_n;
    note := case
      when lower(a.attname) in ('id', 'created_at') and maps_to is null then 'added by Supabase, ignored'
      when maps_to is null       then 'NOT RECOGNIZED: kept in the contact notes. Rename the header, or add it to import_header_aliases'
      when maps_to = 'ignore'    then 'dropped'
      when maps_to = 'extra_notes' then 'appended to the contact notes'
      when maps_to in ('new_contact', 'new_first_name', 'new_email', 'new_org', 'new_website', 'new_linkedin', 'new_notes')
                                 then 'second contact at the same organization (or the contact itself when there is no other name/email column)'
      when v_n = 0               then 'empty column'
      else '' end;
    return next;
  end loop;
end $$;

-- ---------------------------------------------------------------------
-- 4. The import, rewritten for the whole workbook
-- ---------------------------------------------------------------------
create or replace function public.process_import_batch(p_batch_id bigint, p_run_automation boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  b              import_batches;
  r              import_rows;
  v_seg          segments;
  v_email        text;
  v_domain       text;
  v_li           text;
  v_first        text;
  v_last         text;
  v_name_key     text;
  v_org_text     text;
  v_org_key      text;
  v_web_domain   text;
  v_state        char(2);
  v_sourced      date;
  v_contact_id   bigint;
  v_org_id       bigint;
  v_other_id     bigint;
  v_matched      text;
  v_result       text;
  v_detail       text;
  v_cand_org     bigint;
  v_cand_contact bigint;
  v_force_new    boolean;
  v_touch_on     date;
  v_touch_id     bigint;
  v_out          record;
  v_suggest      text;
  v_outcome      text;
  v_outcome_text text;
  v_status       text;
  v_flags        text;
  v_summary      jsonb;
  v_x            jsonb;
  v_channel      text;
  v_campaign_id  bigint;
  v_follow_up    date;
  v_onb_on       date;
  v_funded_on    date;
  v_aum          numeric;
  v_opp          opportunities;
  v_due          date;
  v_k            text;
  v_v            text;
  v_notes_add    text;
begin
  select * into b from import_batches where id = p_batch_id for update;
  if not found then raise exception 'Import batch % not found', p_batch_id; end if;
  if not p_run_automation then
    perform set_config('app.history_load', 'on', true);   -- facts yes, reminders no (see history_load())
  end if;

  for r in
    select * from import_rows
     where batch_id = p_batch_id
       and (processed_at is null or (result = 'needs_review' and review_decision is not null))
     order by row_number, id
  loop
    begin   -- each row in its own sub-transaction: one bad row never stops the batch
      v_contact_id := null; v_org_id := null; v_matched := null; v_result := null; v_detail := null;
      v_cand_org := null; v_cand_contact := null; v_touch_id := null; v_flags := ''; v_campaign_id := null;
      v_x := coalesce(r.extra, '{}');

      if r.review_decision = 'skip' then
        update import_rows set result = 'skipped', result_detail = 'Skipped after review', processed_at = now()
         where id = r.id;
        continue;
      end if;
      v_force_new := coalesce(r.review_decision = 'create_new', false);

      select * into v_seg from segments where code = resolve_segment(r.segment, b.default_segment_code);
      if v_seg.code is null then
        raise exception 'No segment: fill the Segment column or set default_segment_code on the batch';
      end if;

      v_email      := norm_email(r.email);
      v_domain     := nullif(split_part(v_email, '@', 2), '');
      v_li         := norm_linkedin(r.linkedin);
      v_first      := coalesce(nullif(trim(r.first_name), ''), nullif(split_part(trim(coalesce(r.contact, '')), ' ', 1), ''));
      v_last       := coalesce(nullif(trim(r.last_name), ''),
                               nullif(trim(regexp_replace(trim(coalesce(r.contact, '')), '^\S+\s*', '')), ''));
      v_org_text   := nullif(trim(r.org), '');
      -- Customer Loyalty style rows: an individual whose name sits in the "Name" (organization) column
      if v_seg.party_type = 'individual' and v_first is null and v_org_text is not null then
        v_first := nullif(split_part(v_org_text, ' ', 1), '');
        v_last  := nullif(trim(regexp_replace(v_org_text, '^\S+\s*', '')), '');
        v_org_text := null;
      end if;
      v_name_key   := norm_text(coalesce(v_first, '') || ' ' || coalesce(v_last, ''));
      v_org_key    := norm_org_name(v_org_text);
      v_web_domain := norm_domain(r.website);
      v_state      := resolve_state(r.state);
      v_touch_on   := parse_loose_date(r.date_outreached);
      v_sourced    := coalesce(parse_loose_date(r.date_added), v_touch_on, local_date(b.created_at));
      v_channel    := resolve_channel(v_x ->> 'channel', b.default_channel_code);
      if v_email is null and v_li is null and v_name_key is null then
        update import_rows set result = 'skipped', result_detail = 'No name, email or LinkedIn on this row', processed_at = now()
         where id = r.id;
        continue;
      end if;

      -- 1) already in the CRM? (email, then LinkedIn, then a reviewer's decision)
      if v_email is not null then
        select id into v_contact_id from contacts where email_key = v_email;
        if found then v_matched := 'email'; end if;
      end if;
      if v_contact_id is null and v_li is not null then
        select id into v_contact_id from contacts where linkedin_key = v_li;
        if found then v_matched := 'LinkedIn'; end if;
      end if;
      if v_contact_id is null and r.review_decision = 'use_candidate' and r.review_candidate_contact_id is not null then
        v_contact_id := r.review_candidate_contact_id;
        v_matched := 'reviewer: same person';
        update contacts set notes = concat_ws(E'\n', notes, 'Also uses: ' || coalesce(v_email, trim(r.email)))
         where id = v_contact_id and v_email is not null;
      end if;
      -- a tab with no email column (Customer Loyalty): the exact same name at the same organization is the same person
      if v_contact_id is null and b.match_by_name and v_name_key is not null then
        select c.id into v_contact_id
          from contacts c
          left join organizations o on o.id = c.organization_id
         where c.name_key = v_name_key
           and (   (v_org_key is not null and (o.name_key = v_org_key or (v_web_domain is not null and o.domain = v_web_domain)))
                or (v_org_key is null and v_seg.party_type = 'individual' and c.organization_id is null))
         order by c.id limit 1;
        if found then v_matched := 'name'; end if;
      end if;

      -- the email points at one person and the LinkedIn at another
      if v_contact_id is not null and v_li is not null then
        select id into v_other_id from contacts where linkedin_key = v_li and id <> v_contact_id;
        if found then
          update import_rows
             set result = 'needs_review', matched_on = 'email and LinkedIn disagree',
                 review_candidate_contact_id = v_other_id, contact_id = v_contact_id,
                 result_detail = format('Email matches contact #%s but LinkedIn matches contact #%s. Possibly the same person entered twice.',
                                        v_contact_id, v_other_id),
                 processed_at = now()
           where id = r.id;
          continue;
        end if;
      end if;

      if v_contact_id is not null then
        -- fill blanks only, never overwrite what the team already has
        update contacts
           set phone                 = coalesce(phone, nullif(trim(r.phone), '')),
               email                 = coalesce(email, nullif(trim(r.email), '')),
               linkedin_url          = coalesce(linkedin_url, nullif(trim(r.linkedin), '')),
               title                 = coalesce(title, nullif(trim(r.title), '')),
               linkedin_connected_on = coalesce(linkedin_connected_on, parse_yes_or_date(r.added_on_linkedin, v_sourced)),
               notes                 = case when nullif(trim(r.extra_notes), '') is null
                                              or position(trim(r.extra_notes) in coalesce(notes, '')) > 0 then notes
                                            else concat_ws(E'\n', notes, trim(r.extra_notes)) end
         where id = v_contact_id;
        select organization_id into v_org_id from contacts where id = v_contact_id;
        v_result := 'existing_contact';
        select format('Already in the CRM (matched on %s): %s%s. %s%s',
                      v_matched, coalesce(c.full_name, c.email), coalesce(' at ' || o.name, ''),
                      coalesce('Last touch ' || to_char(lt.touched_at, 'Mon DD, YYYY') || ' via ' || tt.name || ': ' || oc.label,
                               'No outreach logged yet'),
                      case when c.do_not_contact then '. DO NOT CONTACT: ' || coalesce(c.dnc_reason, '') else '' end)
          into v_detail
          from contacts c
          left join organizations o on o.id = c.organization_id
          left join lateral (select t.touched_at, t.touch_type, t.outcome_code from touchpoints t
                              where t.contact_id = c.id order by t.touched_at desc limit 1) lt on true
          left join touch_types tt on tt.code = lt.touch_type
          left join outcomes oc on oc.code = lt.outcome_code
         where c.id = v_contact_id;
      else
        -- 2) a new person: is their organization already here?
        if v_seg.party_type = 'organization' then
          if r.review_decision = 'use_candidate' and r.review_candidate_org_id is not null then
            v_org_id := r.review_candidate_org_id; v_matched := 'reviewer: same organization';
          end if;
          if v_org_id is null and v_web_domain is not null then
            select id into v_org_id from organizations where domain = v_web_domain order by id limit 1;
            if found then v_matched := 'website'; end if;
          end if;
          if v_org_id is null and v_org_key is not null then
            select id into v_org_id from organizations where name_key = v_org_key
             order by (state is not distinct from v_state) desc, id limit 1;
            if found then v_matched := 'organization name'; end if;
          end if;
          if v_org_id is null and v_domain is not null
             and not exists (select 1 from freemail_domains f where f.domain = v_domain) then
            select organization_id into v_org_id from contacts
             where email_domain = v_domain and organization_id is not null
             group by organization_id order by count(*) desc limit 1;
            if found then v_matched := 'email domain'; end if;
          end if;
          -- close but not exact (typo, word order, "... Club"): a person decides
          if v_org_id is null and v_org_key is not null and not v_force_new then
            select id into v_cand_org
              from organizations
             where name_key % v_org_key
               and org_names_look_alike(name, v_org_text)
             order by similarity(name_key, v_org_key) desc
             limit 1;
            if v_cand_org is not null then
              update import_rows
                 set result = 'needs_review', matched_on = 'similar organization name',
                     review_candidate_org_id = v_cand_org,
                     result_detail = format('"%s" looks like existing organization "%s". Same organization?',
                                            v_org_text, (select name from organizations where id = v_cand_org)),
                     processed_at = now()
               where id = r.id;
              continue;
            end if;
          end if;
        end if;

        -- 3) same (or nickname / typo) name already there under another email: a person decides
        if not v_force_new and v_name_key is not null then
          select id into v_cand_contact from contacts
           where person_names_look_alike(first_name, last_name, v_first, v_last)
             and (organization_id = v_org_id
                  or (v_org_id is null and organization_id is null and v_seg.party_type = 'individual'
                      and (v_state is null or state is null or state = v_state)))
           order by (name_key = v_name_key) desc, id
           limit 1;
          if found then
            update import_rows
               set result = 'needs_review', matched_on = 'same or similar name', review_candidate_contact_id = v_cand_contact,
                   organization_id = v_org_id,
                   result_detail = format('%s is already in the CRM with email %s. Same person with a new email?',
                                          (select full_name from contacts where id = v_cand_contact),
                                          coalesce((select email from contacts where id = v_cand_contact), '(none)')),
                   processed_at = now()
             where id = r.id;
            continue;
          end if;
        end if;

        -- what already happened at this organization (the "row 2500 vs row 600" hunt)
        if v_org_id is not null then
          select format('Organization already in the CRM (matched on %s). %s other %s there; last touch %s with %s: %s',
                        v_matched, count(distinct c.id), case when count(distinct c.id) = 1 then 'person' else 'people' end,
                        coalesce(to_char(max(t.touched_at), 'Mon DD, YYYY'), 'none'),
                        coalesce((array_agg(c2.full_name order by t.touched_at desc) filter (where t.id is not null))[1], 'nobody'),
                        coalesce((array_agg(oc.label order by t.touched_at desc) filter (where t.id is not null))[1], 'no outreach yet'))
            into v_detail
            from contacts c
            left join touchpoints t on t.contact_id = c.id
            left join contacts c2 on c2.id = t.contact_id
            left join outcomes oc on oc.code = t.outcome_code
           where c.organization_id = v_org_id;
          v_result := 'new_contact_existing_org';
        else
          v_result := 'new_contact';
          if v_seg.party_type = 'organization' and v_org_key is not null then
            insert into organizations (name, segment_code, org_type, website, city, state, reported_aum, owner_id,
                                       source_detail, legacy_ref)
            values (v_org_text, v_seg.code, coalesce(nullif(trim(v_x ->> 'org_type'), ''), b.default_org_type),
                    nullif(trim(r.website), ''), nullif(trim(v_x ->> 'city'), ''), coalesce(v_state, b.default_state),
                    parse_amount(r.aum), b.owner_id, nullif(trim(r.source), ''),
                    b.label || ' / row ' || coalesce(r.row_number::text, '?'))
            returning id into v_org_id;
          end if;
          v_detail := 'Added';
        end if;

        insert into contacts (organization_id, segment_code, first_name, last_name, title, employer, email, phone,
                              linkedin_url, linkedin_connected_on, city, state, prospect_aum, source_channel_code,
                              source_detail, source_event_id, sourced_on, owner_id, notes, legacy_ref)
        values (v_org_id, v_seg.code, v_first, v_last, nullif(trim(r.title), ''),
                case when v_seg.party_type = 'individual' then v_org_text end,
                v_email, nullif(trim(r.phone), ''), nullif(trim(r.linkedin), ''),
                parse_yes_or_date(r.added_on_linkedin, v_sourced),
                nullif(trim(v_x ->> 'city'), ''),
                coalesce(v_state, (select state from organizations where id = v_org_id), b.default_state),
                case when v_seg.party_type = 'individual' then parse_amount(r.aum) end,
                v_channel, nullif(trim(r.source), ''), b.event_id, v_sourced, b.owner_id,
                nullif(concat_ws(E'\n', nullif(trim(r.notes), ''), nullif(trim(r.extra_notes), '')), ''),
                b.label || ' / row ' || coalesce(r.row_number::text, '?'))
        returning id into v_contact_id;
        if v_email is null and nullif(trim(r.email), '') is not null then
          v_detail := v_detail || format('. Email "%s" is not valid and was left blank', trim(r.email));
        end if;
      end if;

      -- 3b) the workbook's extra columns -------------------------------------------------
      -- organization facts (fill blanks; "Reach Out Again?" is newer information and overwrites)
      if v_org_id is not null then
        update organizations
           set org_type              = coalesce(org_type, nullif(trim(v_x ->> 'org_type'), ''), b.default_org_type),
               city                  = coalesce(city, nullif(trim(v_x ->> 'city'), '')),
               reported_aum          = coalesce(reported_aum, parse_amount(r.aum)),
               employee_count        = coalesce(employee_count, nullif(regexp_replace(coalesce(v_x ->> 'employee_count', ''), '[^0-9]', '', 'g'), '')::int),
               plans_served          = coalesce(plans_served, nullif(regexp_replace(coalesce(v_x ->> 'plans_served', ''), '[^0-9]', '', 'g'), '')::int),
               commissions           = coalesce(commissions, parse_amount(v_x ->> 'commissions')),
               shared_employers      = coalesce(shared_employers, nullif(trim(v_x ->> 'shared_employers'), '')),
               advertises_retirement = coalesce(advertises_retirement, parse_yes_no(v_x ->> 'advertises_retirement')),
               reach_out_again       = coalesce(parse_yes_no(v_x ->> 'reach_out_again'), reach_out_again),
               no_reach_out_reason   = coalesce(nullif(trim(v_x ->> 'no_reach_out_reason'), ''), no_reach_out_reason),
               mailing_address       = coalesce(mailing_address, nullif(trim(v_x ->> 'mailing_address'), ''))
         where id = v_org_id;
      end if;

      -- contact facts
      v_notes_add := null;
      if nullif(trim(v_x ->> 'status'), '') is not null and nullif(trim(r.outcome), '') is not null then
        v_notes_add := concat_ws(E'\n', v_notes_add, 'Status (sheet): ' || trim(v_x ->> 'status'));
      end if;
      if nullif(trim(v_x ->> 'outcome_2'), '') is not null then
        v_notes_add := concat_ws(E'\n', v_notes_add, 'Outcome 2 (sheet): ' || trim(v_x ->> 'outcome_2'));
      end if;
      if nullif(trim(v_x ->> 'no_reach_out_reason'), '') is not null and v_org_id is null then
        v_notes_add := concat_ws(E'\n', v_notes_add, 'Reason not to reach out again: ' || trim(v_x ->> 'no_reach_out_reason'));
      end if;
      update contacts
         set city            = coalesce(city, nullif(trim(v_x ->> 'city'), '')),
             mailing_address = coalesce(mailing_address, nullif(trim(v_x ->> 'mailing_address'), '')),
             activity_status = coalesce(case when lower(trim(coalesce(v_x ->> 'activity_status', ''))) ~ '^(dorm|inactive|parked)' then 'dormant'
                                             when lower(trim(coalesce(v_x ->> 'activity_status', ''))) ~ '^active' then 'active' end,
                                        activity_status),
             source_channel_code = coalesce(source_channel_code, v_channel),
             tags            = (select coalesce(array_agg(distinct x), '{}') from unnest(tags || b.tags) x),
             notes           = case when v_notes_add is null or position(v_notes_add in coalesce(notes, '')) > 0 then notes
                                    else concat_ws(E'\n', notes, v_notes_add) end
       where id = v_contact_id;
      if parse_yes_no(v_x ->> 'newsletter') then
        perform add_to_newsletter(v_contact_id, v_sourced, 'sheet: ' || b.label);
      end if;

      -- flags the rules raised on this person
      select concat_ws('. ',
               case when do_not_contact then 'FLAGGED DO NOT CONTACT: ' || coalesce(dnc_reason, '') end,
               case when is_university_affiliated then 'University contact: founder may know them' end)
        into v_flags
        from contacts where id = v_contact_id;
      if coalesce(v_flags, '') <> '' then v_detail := v_detail || '. ' || v_flags; end if;

      -- "Batch" column (Small Biz list) -> campaign
      if nullif(trim(v_x ->> 'campaign'), '') is not null then
        select id into v_campaign_id from campaigns where lower(name) = lower(trim(v_x ->> 'campaign'));
        if v_campaign_id is null then
          insert into campaigns (name, channel_code, segment_code, description)
          values (trim(v_x ->> 'campaign'), b.default_channel_code, v_seg.code, 'From ' || b.label)
          returning id into v_campaign_id;
        end if;
      end if;

      -- 4) the outreach columns become a touchpoint
      v_outcome_text := coalesce(nullif(trim(r.outcome), ''), nullif(trim(v_x ->> 'status'), ''));
      if v_touch_on is null and b.default_outcome_code is not null and v_outcome_text is null then
        v_touch_on := v_sourced;     -- e.g. the Wrong Emails tab: the bounce is the fact, the date is secondary
      end if;
      if v_touch_on is not null then
        select * into v_out from match_outcome(v_outcome_text);
        v_suggest := case when exists (select 1 from outcomes o
                                        where o.code = v_out.outcome_code and b.default_touch_type = any (o.applies_to))
                          then v_out.outcome_code end;
        if v_outcome_text is null and b.default_outcome_code is not null then
          v_outcome := b.default_outcome_code; v_status := 'confirmed';
        elsif v_outcome_text is null then                                     -- blank = still no response
          v_outcome := case when b.default_touch_type in ('email', 'check_in') then 'NO_RESPONSE' end;
          v_status  := 'confirmed';
        elsif lower(trim(v_outcome_text)) in ('review', 'needs review', 'to review', '?') then
          v_outcome := case when b.default_touch_type in ('email', 'check_in') then 'NO_RESPONSE' end;
          v_status  := 'needs_review'; v_suggest := null;
        elsif v_suggest is not null and v_out.is_exact then                   -- a clean label
          v_outcome := v_suggest; v_status := 'confirmed';
        elsif v_suggest is not null then                                      -- phrase inside a pasted reply, or a hint
          v_outcome := coalesce(b.default_outcome_code,
                                case when b.default_touch_type in ('email', 'check_in') then 'NO_RESPONSE' end);
          v_status  := 'needs_review';
        else                                                                  -- could not tell
          v_outcome := coalesce(b.default_outcome_code,
                                case when b.default_touch_type in ('email', 'check_in') then 'NO_RESPONSE' end);
          v_status  := 'needs_review';
        end if;
        -- a blank outcome but a pasted reply: let the reply suggest
        if v_outcome_text is null and nullif(trim(v_x ->> 'response_notes'), '') is not null then
          select * into v_out from match_outcome(v_x ->> 'response_notes');
          if v_out.outcome_code is not null and exists (select 1 from outcomes o where o.code = v_out.outcome_code
                                                          and b.default_touch_type = any (o.applies_to)) then
            v_suggest := v_out.outcome_code; v_status := 'needs_review';
          end if;
        end if;

        v_follow_up := parse_loose_date(r.follow_up_on);
        if v_follow_up is null and b.default_follow_up_days is not null then
          v_follow_up := greatest(v_touch_on + b.default_follow_up_days, local_today());
        end if;

        -- re-importing the same sheet does not create the touch twice
        select id into v_touch_id from touchpoints
         where contact_id = v_contact_id and touch_type = b.default_touch_type and local_date(touched_at) = v_touch_on
         limit 1;
        if v_touch_id is null then
          insert into touchpoints (contact_id, touch_type, direction, touched_at, campaign_id, event_id,
                                   outcome_code, outcome_status, outcome_raw, response_excerpt,
                                   ai_suggested_outcome, ai_confidence, ai_reason, notes, owner_id, follow_up_on)
          values (v_contact_id, b.default_touch_type,
                  case when b.default_touch_type = 'event' then 'in_person' else 'outbound' end,
                  (v_touch_on + time '09:00') at time zone 'America/Denver', coalesce(v_campaign_id, b.campaign_id), b.event_id,
                  v_outcome, v_status, v_outcome_text, nullif(trim(v_x ->> 'response_notes'), ''),
                  case when v_status = 'needs_review' then v_suggest end,
                  case when v_status = 'needs_review' and v_suggest is not null then 0.6 end,
                  case when v_status = 'needs_review' and v_suggest is not null and v_out.phrase is not null
                       then format('Matched "%s" in the sheet', v_out.phrase)
                       when v_status = 'needs_review' then 'Could not match the Outcome text; a person decides' end,
                  nullif(trim(r.next_steps), ''), b.owner_id, v_follow_up)
          returning id into v_touch_id;
        end if;
      else
        v_follow_up := parse_loose_date(r.follow_up_on);
        if v_follow_up is null and b.default_follow_up_days is not null then
          v_follow_up := greatest(v_sourced + b.default_follow_up_days, local_today());
        end if;
        if v_outcome_text is not null then      -- an outcome / status with no date: keep the words
          update contacts set notes = concat_ws(E'\n', notes, 'Outcome (sheet, no date): ' || v_outcome_text)
           where id = v_contact_id and position('Outcome (sheet, no date): ' || v_outcome_text in coalesce(notes, '')) = 0;
        end if;
      end if;

      -- the sheet's next reach-out date (or the section's "check back in N months") -> one open reminder
      -- (live imports with an outreach date leave this to the outcome rules)
      if v_follow_up is not null and (v_touch_on is null or not p_run_automation)
         and not exists (select 1 from reminders
                          where contact_id = v_contact_id and status in ('open', 'snoozed')
                            and reminder_type in ('follow_up', 'ooo_follow_up', 'post_call', 'check_in')) then
        insert into reminders (reminder_type, contact_id, organization_id, touchpoint_id, due_on, title, details, assigned_to, created_by)
        select 'follow_up', c.id, c.organization_id, v_touch_id, v_follow_up,
               'Follow up: ' || coalesce(c.full_name, c.email) || coalesce(' (' || o.name || ')', ''),
               'Next reach-out date from ' || b.label
                 || coalesce(E'\n' || nullif(trim(r.next_steps), ''), '')
                 || coalesce(E'\nStatus: ' || nullif(trim(v_x ->> 'status'), ''), ''),
               coalesce(c.owner_id, b.owner_id), 'import'
          from contacts c left join organizations o on o.id = c.organization_id
         where c.id = v_contact_id and not c.do_not_contact;
      end if;

      -- 5) Onboarded tab: Sent Onboarding / Account Funded Date / AUM -> the opportunity
      v_onb_on    := parse_loose_date(v_x ->> 'onboarding_sent_on');
      v_funded_on := parse_loose_date(v_x ->> 'funded_on');
      if v_onb_on is null and v_funded_on is null and parse_yes_no(v_x ->> 'onboarding_sent_on') then
        v_onb_on := coalesce(v_touch_on, v_sourced);                        -- "Yes" with no date
      end if;
      if v_onb_on is not null or v_funded_on is not null then
        v_aum := parse_amount(r.aum);
        select * into v_opp from opportunities op
         where (op.contact_id = v_contact_id
                or (v_seg.party_type = 'organization' and v_org_id is not null and op.organization_id = v_org_id))
         order by (op.stage not in ('funded', 'lost')) desc, (op.contact_id = v_contact_id) desc, op.opened_on desc
         limit 1;
        if not found then
          insert into opportunities (contact_id, organization_id, segment_code, state, stage, source_channel_code,
                                     converting_channel_code, converting_touchpoint_id, opened_on, onboarding_started_on,
                                     funded_on, funded_aum, expected_aum, owner_id, notes)
          values (v_contact_id, case when v_seg.party_type = 'organization' then v_org_id end, v_seg.code, v_state,
                  case when v_funded_on is not null and v_aum is not null then 'funded' else 'onboarding' end,
                  v_channel, b.default_channel_code, v_touch_id,
                  coalesce(v_touch_on, v_onb_on, v_funded_on), coalesce(v_onb_on, v_funded_on),
                  case when v_aum is not null then v_funded_on end,
                  case when v_funded_on is not null then v_aum end, v_aum, b.owner_id,
                  'From ' || b.label)
          returning * into v_opp;
        else
          update opportunities
             set stage                 = case when v_funded_on is not null and coalesce(v_aum, funded_aum) is not null then 'funded'
                                              when stage_rank('onboarding') > stage_rank(stage) then 'onboarding' else stage end,
                 onboarding_started_on = coalesce(onboarding_started_on, v_onb_on, v_funded_on),
                 funded_on             = case when coalesce(v_aum, funded_aum) is not null then coalesce(funded_on, v_funded_on) else funded_on end,
                 funded_aum            = coalesce(funded_aum, case when v_funded_on is not null then v_aum end),
                 expected_aum          = coalesce(expected_aum, v_aum),
                 closed_on             = case when v_funded_on is not null and coalesce(v_aum, funded_aum) is not null
                                              then coalesce(closed_on, v_funded_on) else closed_on end
           where id = v_opp.id
           returning * into v_opp;
        end if;
        if v_funded_on is not null and v_opp.funded_aum is null then
          v_detail := v_detail || format('. Funded on %s but no AUM in the sheet: left in onboarding until funded_aum is entered',
                                         to_char(v_funded_on, 'Mon DD, YYYY'));
          insert into reminders (reminder_type, contact_id, organization_id, opportunity_id, due_on, title, details, assigned_to, created_by)
          select 'onboarding_task', v_contact_id, v_opp.organization_id, v_opp.id, local_today(),
                 'Enter the funded AUM: ' || coalesce(c.full_name, c.email),
                 'The Onboarded sheet shows this account funded on ' || to_char(v_funded_on, 'Mon DD, YYYY')
                   || ' but has no AUM. Fill opportunities.funded_aum and set the stage to funded.',
                 coalesce(c.owner_id, b.owner_id), 'import'
            from contacts c where c.id = v_contact_id
             and not exists (select 1 from reminders x where x.opportunity_id = v_opp.id and x.status in ('open', 'snoozed')
                                                          and x.reminder_type = 'onboarding_task');
        end if;
        update contacts set tags = (select coalesce(array_agg(distinct x), '{}') from unnest(tags || '{client}') x)
         where id = v_contact_id;
      end if;

      -- 6) Customer Loyalty tab: card and check-in dates -> reminders (past dates logged as done)
      for v_k, v_v in
        select * from (values ('loyalty_thanksgiving', 'thanksgiving_card'), ('loyalty_referral_1', 'referral_check_in'),
                              ('loyalty_referral_2', 'referral_check_in'), ('loyalty_referral_3', 'referral_check_in')) t(k, typ)
      loop
        v_due := parse_loose_date(v_x ->> v_k);
        continue when v_due is null;
        if not exists (select 1 from reminders where contact_id = v_contact_id and reminder_type = v_v and due_on = v_due) then
          insert into reminders (reminder_type, contact_id, organization_id, due_on, title, details, assigned_to, created_by,
                                 status, completed_at)
          select v_v, c.id, c.organization_id, v_due,
                 (select label from reminder_types where code = v_v) || ': ' || coalesce(c.full_name, c.email)
                   || coalesce(' (' || o.name || ')', ''),
                 'From ' || b.label || coalesce(E'\nMail to: ' || coalesce(c.mailing_address, o.mailing_address), ''),
                 coalesce(c.owner_id, b.owner_id), 'import',
                 case when v_due < local_today() then 'done' else 'open' end,
                 case when v_due < local_today() then (v_due + time '12:00') at time zone 'America/Denver' end
            from contacts c left join organizations o on o.id = c.organization_id
           where c.id = v_contact_id;
        end if;
      end loop;

      update import_rows
         set result = v_result, result_detail = v_detail, matched_on = v_matched,
             contact_id = v_contact_id,
             organization_id = (select organization_id from contacts where id = v_contact_id),
             touchpoint_id = v_touch_id, processed_at = now()
       where id = r.id;

    exception when others then
      update import_rows set result = 'error', result_detail = sqlerrm, processed_at = now() where id = r.id;
    end;
  end loop;

  select jsonb_build_object(
           'batch',                          b.label,
           'rows',                           count(*),
           'new_contacts',                   count(*) filter (where ir.result = 'new_contact'),
           'new_contacts_at_known_orgs',     count(*) filter (where ir.result = 'new_contact_existing_org'),
           'already_in_crm',                 count(*) filter (where ir.result = 'existing_contact'),
           'needs_review',                   count(*) filter (where ir.result = 'needs_review'),
           'skipped',                        count(*) filter (where ir.result = 'skipped'),
           'errors',                         count(*) filter (where ir.result = 'error'),
           'flagged_do_not_contact',         count(*) filter (where c.do_not_contact),
           'flagged_university',             count(*) filter (where c.is_university_affiliated),
           'outcomes_to_confirm',            count(*) filter (where t.outcome_status = 'needs_review'))
    into v_summary
    from import_rows ir
    left join contacts c    on c.id = ir.contact_id
    left join touchpoints t on t.id = ir.touchpoint_id
   where ir.batch_id = p_batch_id;

  update import_batches set status = 'processed', processed_at = now(), summary = v_summary where id = p_batch_id;
  perform set_config('app.history_load', 'off', true);   -- back to normal for the rest of the transaction
  return v_summary;
end $$;

create or replace function public.import_uploaded_table(p_table regclass, p_label text, p_segment text DEFAULT NULL::text, p_channel text DEFAULT 'COLD_EMAIL'::text, p_touch_type text DEFAULT 'email'::text, p_state character DEFAULT NULL::bpchar, p_event_id bigint DEFAULT NULL::bigint, p_campaign_id bigint DEFAULT NULL::bigint, p_owner_id bigint DEFAULT NULL::bigint, p_run_automation boolean DEFAULT false, p_org_type text DEFAULT NULL::text, p_default_outcome text DEFAULT NULL::text, p_follow_up_days integer DEFAULT NULL::integer, p_tags text[] DEFAULT '{}'::text[], p_match_by_name boolean DEFAULT false, p_header_map jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_batch     bigint;
  v_row       jsonb;
  v_key       text;
  v_val       text;
  v_field     text;
  v_f         jsonb;
  v_x         jsonb;
  v_extra     text;
  v_n         int := 0;
  v_order     text := '';
  v_used      jsonb := '{}';
  v_kept      text[] := '{}';
  v_split     int := 0;
  v_core      text[] := '{date_added,source,contact,first_name,last_name,title,email,org,website,linkedin,added_on_linkedin,phone,aum,state,segment,notes,date_outreached,outcome,next_steps,follow_up_on}';
  v_outcome   text;
begin
  if exists (select 1 from pg_attribute where attrelid = p_table and attname = 'id' and not attisdropped) then
    v_order := ' order by t.id';                 -- keep the sheet's row order
  end if;
  if p_default_outcome is not null then
    select code into v_outcome from outcomes where code = upper(p_default_outcome);
    if v_outcome is null then
      select outcome_code into v_outcome from match_outcome(p_default_outcome);
    end if;
    if v_outcome is null then raise exception 'Unknown default outcome "%"', p_default_outcome; end if;
  end if;

  insert into import_batches (label, source_file, default_segment_code, default_channel_code, default_touch_type,
                              default_state, campaign_id, event_id, owner_id, default_org_type, default_outcome_code,
                              default_follow_up_days, tags, match_by_name, header_map, history_load)
  values (p_label, p_table::text, resolve_segment(p_segment, null), p_channel, p_touch_type,
          p_state, p_campaign_id, p_event_id, p_owner_id, p_org_type, v_outcome,
          p_follow_up_days, coalesce(p_tags, '{}'), p_match_by_name, coalesce(p_header_map, '{}'), not p_run_automation)
  returning id into v_batch;

  for v_row in execute format('select to_jsonb(t) from %s t%s', p_table, v_order) loop
    v_n := v_n + 1;
    v_f := '{}'; v_x := '{}';
    v_extra := null;
    for v_key, v_val in select key, value from jsonb_each_text(v_row) loop
      continue when v_val is null or btrim(v_val) = '';
      v_field := resolve_header(v_key, p_header_map);
      if v_field is null then
        continue when lower(v_key) in ('id', 'created_at');      -- columns Supabase adds by itself
        v_extra := concat_ws(E'\n', v_extra, v_key || ': ' || v_val);
        if not (v_key = any (v_kept)) then v_kept := v_kept || v_key; end if;
      elsif v_field = 'ignore' then
        continue;
      elsif v_field = 'extra_notes' then
        v_extra := concat_ws(E'\n', v_extra, v_key || ': ' || v_val);
        v_used := v_used || jsonb_build_object(v_key, v_field);
      elsif v_field = any (v_core) then
        -- two headers for the same field ("Note" and "Notes"): text fields are joined, single-value
        -- fields (dates, email, AUM ...) keep the first value and the second goes to the notes
        if v_field in ('notes', 'next_steps', 'outcome', 'source', 'title') or (v_f ->> v_field) is null then
          v_f := v_f || jsonb_build_object(v_field,
                   concat_ws(case when v_field in ('notes', 'next_steps') then E'\n' else ' ' end, v_f ->> v_field, v_val));
        elsif (v_f ->> v_field) <> v_val then
          v_extra := concat_ws(E'\n', v_extra, v_key || ': ' || v_val);
        end if;
        v_used := v_used || jsonb_build_object(v_key, v_field);
      else
        if (v_x ->> v_field) is null or v_field in ('status', 'response_notes', 'new_notes', 'no_reach_out_reason') then
          v_x := v_x || jsonb_build_object(v_field, concat_ws(E'\n', v_x ->> v_field, v_val));
        elsif (v_x ->> v_field) <> v_val then
          v_extra := concat_ws(E'\n', v_extra, v_key || ': ' || v_val);
        end if;
        v_used := v_used || jsonb_build_object(v_key, v_field);
      end if;
    end loop;
    continue when v_f = '{}' and v_x = '{}';                      -- an empty line in the sheet

    -- a sheet whose only people columns are the NEW CONTACT ones (Cold Nonprofits 2026): they are the person
    if coalesce(v_f ->> 'contact', v_f ->> 'email', v_f ->> 'linkedin') is null
       and coalesce(v_x ->> 'new_contact', v_x ->> 'new_email', v_x ->> 'new_linkedin') is not null then
      v_f := v_f || jsonb_strip_nulls(jsonb_build_object(
               'contact', v_x ->> 'new_contact', 'first_name', coalesce(v_x ->> 'new_first_name', v_f ->> 'first_name'),
               'email', v_x ->> 'new_email',
               'linkedin', v_x ->> 'new_linkedin', 'org', coalesce(v_f ->> 'org', v_x ->> 'new_org'),
               'website', coalesce(v_f ->> 'website', v_x ->> 'new_website'),
               'notes', concat_ws(E'\n', v_f ->> 'notes', v_x ->> 'new_notes')));
      v_x := v_x - '{new_contact,new_first_name,new_email,new_linkedin,new_org,new_website,new_notes}'::text[];
    end if;

    insert into import_rows (batch_id, row_number, date_added, source, contact, first_name, last_name, title, email,
                             org, website, linkedin, added_on_linkedin, phone, aum, state, segment, notes,
                             date_outreached, outcome, next_steps, follow_up_on, extra_notes, extra)
    values (v_batch, v_n + 1, v_f->>'date_added', v_f->>'source', v_f->>'contact', v_f->>'first_name',
            v_f->>'last_name', v_f->>'title', v_f->>'email', v_f->>'org', v_f->>'website', v_f->>'linkedin',
            v_f->>'added_on_linkedin', v_f->>'phone', v_f->>'aum', v_f->>'state', v_f->>'segment', v_f->>'notes',
            v_f->>'date_outreached', v_f->>'outcome', v_f->>'next_steps', v_f->>'follow_up_on', v_extra,
            v_x - '{new_contact,new_first_name,new_email,new_linkedin,new_org,new_website,new_notes}'::text[]);

    -- Master list: the NEW CONTACT columns are a second person at the same organization,
    -- sourced on "Date Source Approved", with no touch yet (the 2026 tab brings the 2026 outreach)
    if coalesce(v_x ->> 'new_contact', v_x ->> 'new_email', v_x ->> 'new_linkedin') is not null then
      v_split := v_split + 1;
      insert into import_rows (batch_id, row_number, date_added, source, contact, first_name, email, org, website,
                               linkedin, state, segment, notes, extra)
      values (v_batch, v_n + 1, coalesce(v_x ->> 'date_source_approved', v_f ->> 'date_added'), v_f ->> 'source',
              v_x ->> 'new_contact', v_x ->> 'new_first_name', v_x ->> 'new_email',
              coalesce(v_x ->> 'new_org', v_f ->> 'org'), coalesce(v_x ->> 'new_website', v_f ->> 'website'),
              v_x ->> 'new_linkedin', v_f ->> 'state', v_f ->> 'segment', v_x ->> 'new_notes',
              jsonb_build_object('derived_from', 'NEW CONTACT columns of row ' || (v_n + 1)));
    end if;
  end loop;

  return process_import_batch(v_batch, p_run_automation)
         || jsonb_build_object('batch_id', v_batch, 'columns_used', v_used, 'columns_kept_in_notes', to_jsonb(v_kept),
                               'new_contact_rows_split_off', v_split);
end $$;

create or replace function public.import_gaard_tab(p_table regclass, p_tab text, p_owner_id bigint DEFAULT NULL::bigint, p_run_automation boolean DEFAULT false, p_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  p import_tab_profiles;
begin
  select * into p from import_tab_profiles where lower(tab) = lower(p_tab);
  if not found then
    raise exception 'Unknown tab "%". Known tabs: %', p_tab,
      (select string_agg(tab, ', ' order by sort_order) from import_tab_profiles);
  end if;
  return import_uploaded_table(
           p_table, coalesce(p_label, p.tab), p.segment, p.channel_code, p.touch_type, null, null, null, p_owner_id,
           p_run_automation, p.org_type, p.default_outcome_code, p.follow_up_days, p.tags, p.match_by_name, p.header_map)
         || jsonb_build_object('tab', p.tab);
end $$;

-- ---------------------------------------------------------------------
-- 5. Rules that stand down during a history load
-- ---------------------------------------------------------------------
create or replace function public.touchpoints_before_write() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  c  contacts;
  tt touch_types;
  o  outcomes;
begin
  select * into c  from contacts    where id   = new.contact_id;
  select * into tt from touch_types where code = new.touch_type;
  new.organization_id := coalesce(new.organization_id, c.organization_id);
  new.owner_id        := coalesce(new.owner_id, c.owner_id);

  -- do-not-contact: block new emails / calls after someone is flagged (old history is only recorded)
  if tg_op = 'INSERT' and new.direction = 'outbound' and new.touch_type in ('email', 'call', 'check_in')
     and c.do_not_contact and (c.dnc_on is null or local_date(new.touched_at) > c.dnc_on)
     and not history_load() then
    raise exception 'DO NOT CONTACT: % is on the do-not-contact list (%)',
                    coalesce(c.full_name, c.email), coalesce(c.dnc_reason, 'no reason given')
      using hint = 'Remove the flag on the contact, or the matching flag rule, if this is intentional.';
  end if;

  -- outreach emails start as "No response" until a reply comes in
  if new.outcome_code is null and new.direction = 'outbound' and new.touch_type in ('email', 'check_in') then
    new.outcome_code := 'NO_RESPONSE';
  end if;

  -- the outcome has to fit the kind of touch
  if new.outcome_code is not null then
    select * into o from outcomes where code = new.outcome_code;
    if not (new.touch_type = any (o.applies_to)) then
      raise exception 'Outcome "%" cannot be used on a "%" touch (allowed on: %)',
                      o.label, tt.name, array_to_string(o.applies_to, ', ');
    end if;
  end if;
  if new.ai_suggested_outcome is not null and not exists (
       select 1 from outcomes where code = new.ai_suggested_outcome and new.touch_type = any (applies_to)) then
    raise exception 'Suggested outcome % does not fit a "%" touch', new.ai_suggested_outcome, tt.name;
  end if;

  -- a person confirmed a suggested outcome
  if tg_op = 'UPDATE' and new.outcome_status = 'confirmed' and old.outcome_status = 'needs_review' then
    new.confirmed_at := coalesce(new.confirmed_at, now());
  end if;

  if tg_op = 'UPDATE' then new.updated_at := now(); end if;
  return new;
end $$;

create or replace function public.apply_outcome_rules(p_touch public.touchpoints) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  o          outcomes;
  c          contacts;
  seg        segments;
  tt         touch_types;
  v_day      date := local_date(p_touch.touched_at);
  v_label    text;
  v_dnc      boolean;
  v_due      date;
  v_opp      opportunities;
  v_latest   boolean;
  v_streak   int;
begin
  select * into o   from outcomes    where code = p_touch.outcome_code;
  if not found then return; end if;
  select * into c   from contacts    where id   = p_touch.contact_id;
  select * into seg from segments    where code = c.segment_code;
  select * into tt  from touch_types where code = p_touch.touch_type;
  v_label := coalesce(c.full_name, c.email, 'Contact #' || c.id)
             || coalesce(' (' || (select name from organizations where id = c.organization_id) || ')', '');

  -- 1. contact flags ----------------------------------------------------
  if o.sets_do_not_contact then
    update contacts
       set do_not_contact = true,
           dnc_reason     = coalesce(dnc_reason, o.label),
           dnc_on         = coalesce(dnc_on, v_day)
     where id = c.id;
    update reminders set status = 'dismissed', completed_at = now()
     where contact_id = c.id and status in ('open', 'snoozed');
  end if;

  if p_touch.touch_type in ('email', 'check_in') then
    if o.marks_email_bad then
      update contacts set email_status = 'bounced' where id = c.id;
    elsif o.code = 'WRONG_PERSON' then
      update contacts set email_status = 'wrong_person' where id = c.id;
    elsif o.counts_as_response then
      update contacts set email_status = 'valid' where id = c.id and email_status <> 'valid';
    end if;
  end if;

  if o.adds_to_newsletter then
    perform add_to_newsletter(c.id, v_day, 'auto: ' || o.label);
  end if;

  v_dnc := c.do_not_contact or o.sets_do_not_contact;

  -- 2. next outreach date = the reminder ----------------------------------
  -- only the most recent touch sets the cadence (back-filled history does not)
  v_latest := not exists (
    select 1 from touchpoints t
     where t.contact_id = c.id and t.id <> p_touch.id and t.touched_at > p_touch.touched_at);

  if v_latest and not history_load() then
    update reminders set status = 'superseded', completed_at = now()
     where contact_id = c.id and status in ('open', 'snoozed')
       and reminder_type in ('follow_up', 'ooo_follow_up', 'post_call', 'event_follow_up',
                             'referral_follow_up', 'check_in');

    if o.reminder_type is not null and not v_dnc then
      -- e.g. the 3rd unanswered dial in a row: stop calling weekly, go back to quarterly
      if o.retry_limit is not null then
        select count(*) into v_streak
          from touchpoints t join outcomes x on x.code = t.outcome_code
         where t.contact_id = c.id and t.touch_type = p_touch.touch_type and x.retry_limit is not null
           and t.touched_at <= p_touch.touched_at
           and t.touched_at > coalesce((select max(t2.touched_at) from touchpoints t2
                                          join outcomes x2 on x2.code = t2.outcome_code
                                         where t2.contact_id = c.id and x2.retry_limit is null
                                           and t2.touched_at <= p_touch.touched_at), '-infinity');
      end if;
      v_due := coalesce(
        p_touch.follow_up_on,                                                   -- "check back in October"
        case when o.code = 'OUT_OF_OFFICE' then p_touch.ooo_return_on + 1 end, -- back from vacation
        case when v_streak >= o.retry_limit then v_day + o.after_limit_days end,
        v_day + o.next_outreach_days);                                          -- default cadence
      if v_due is not null then
        insert into reminders (reminder_type, contact_id, organization_id, touchpoint_id, due_on,
                               title, details, follow_up_style, assigned_to)
        values (o.reminder_type, c.id, c.organization_id, p_touch.id, v_due,
                (select label from reminder_types where code = o.reminder_type) || ': ' || v_label,
                'Last outcome: ' || o.label || ' (' || tt.name || ', ' || to_char(v_day, 'Mon DD, YYYY') || ')'
                  || coalesce(E'\n' || p_touch.notes, ''),
                c.follow_up_style, c.owner_id);
      end if;
    end if;
  end if;

  -- 3. pipeline (affiliates are partners, not prospects: no opportunity for them) ----
  if o.sets_stage is not null and seg.segment_group <> 'Affiliates' then
    -- the open opportunity for this person, or for their organization
    select * into v_opp from opportunities op
     where op.stage not in ('funded', 'lost')
       and (op.contact_id = c.id
            or (seg.party_type = 'organization' and c.organization_id is not null
                and op.organization_id = c.organization_id))
     order by (op.contact_id = c.id) desc, op.opened_on desc
     limit 1;

    if found then
      if o.sets_stage = 'lost' then
        update opportunities
           set stage = 'lost', closed_on = coalesce(closed_on, v_day), lost_reason = coalesce(lost_reason, o.label)
         where id = v_opp.id;
      else
        update opportunities
           set stage = case when stage_rank(o.sets_stage) > stage_rank(v_opp.stage) then o.sets_stage else stage end,
               first_call_on = coalesce(first_call_on, case when p_touch.touch_type = 'meeting' then v_day end),
               hot_on = case when o.sets_stage = 'hot' then coalesce(hot_on, v_day) else hot_on end,
               onboarding_started_on = case when o.sets_stage = 'onboarding'
                                            then coalesce(onboarding_started_on, v_day) else onboarding_started_on end
         where id = v_opp.id;
      end if;
    elsif o.sets_stage <> 'lost'
      -- a touch older than a deal that already closed for this person / organization is history, not a new deal
      and not exists (
            select 1 from opportunities op
             where op.stage in ('funded', 'lost')
               and (op.contact_id = c.id
                    or (seg.party_type = 'organization' and c.organization_id is not null
                        and op.organization_id = c.organization_id))
               and coalesce(op.closed_on, op.funded_on, op.opened_on) >= v_day) then
      -- a call was just booked: open the opportunity
      insert into opportunities (contact_id, organization_id, segment_code, state, stage,
                                 source_channel_code, converting_channel_code, converting_touchpoint_id,
                                 source_event_id, rfp_id, opened_on, first_call_on, hot_on,
                                 onboarding_started_on, owner_id)
      values (c.id,
              case when seg.party_type = 'organization' then c.organization_id end,
              c.segment_code, c.state, o.sets_stage,
              coalesce(c.source_channel_code, tt.channel_code, 'COLD_EMAIL'),
              tt.channel_code, p_touch.id, c.source_event_id, p_touch.rfp_id, v_day,
              case when p_touch.touch_type = 'meeting' then v_day else p_touch.follow_up_on end,
              case when o.sets_stage = 'hot' then v_day end,
              case when o.sets_stage = 'onboarding' then v_day end,
              c.owner_id);
    end if;
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 6. The master list shows the two new contact columns
-- ---------------------------------------------------------------------
create or replace view public.v_contacts with (security_invoker = true) as
 SELECT c.id AS contact_id,
    c.full_name,
    c.first_name,
    c.last_name,
    c.title,
    c.organization_id,
    COALESCE(o.name, c.employer) AS organization,
    sg.segment_group,
    sg.name AS segment,
    c.segment_code,
    c.state,
    st.name AS state_name,
    c.city,
    c.email,
    c.email_status,
    c.phone,
    c.linkedin_url,
    c.linkedin_connected_on,
    ch.name AS source_channel,
    c.source_detail,
    ev.name AS source_event,
    c.sourced_on,
    public.local_date(lt.touched_at) AS last_touch_on,
    ltt.name AS last_touch_type,
    lo.label AS last_outcome,
    public.local_date(ls.last_spoke_at) AS last_spoke_on,
    nr.due_on AS next_outreach_on,
    rt.label AS next_action,
    COALESCE(tc.touches, (0)::bigint) AS touches,
    COALESCE(tc.emails_sent, (0)::bigint) AS emails_sent,
    COALESCE(tc.calls_dialed, (0)::bigint) AS calls_dialed,
    op.stage AS pipeline_stage,
    op.expected_aum,
    op.funded_aum,
    COALESCE(o.reported_aum, c.prospect_aum) AS prospect_aum,
    c.is_decision_maker,
    c.is_university_affiliated,
    c.do_not_contact,
    c.dnc_reason,
    c.newsletter_status,
    c.follow_up_style,
    tm.full_name AS owner,
    c.tags,
    c.notes,
    c.created_at,
    c.activity_status,
    c.mailing_address
   FROM ((((((((((((((public.contacts c
     JOIN public.segments sg ON ((sg.code = c.segment_code)))
     LEFT JOIN public.organizations o ON ((o.id = c.organization_id)))
     LEFT JOIN public.us_states st ON ((st.code = c.state)))
     LEFT JOIN public.channels ch ON ((ch.code = c.source_channel_code)))
     LEFT JOIN public.events ev ON ((ev.id = c.source_event_id)))
     LEFT JOIN public.team_members tm ON ((tm.id = c.owner_id)))
     LEFT JOIN LATERAL ( SELECT t.touched_at,
            t.touch_type,
            t.outcome_code
           FROM public.touchpoints t
          WHERE (t.contact_id = c.id)
          ORDER BY t.touched_at DESC, t.id DESC
         LIMIT 1) lt ON (true))
     LEFT JOIN public.touch_types ltt ON ((ltt.code = lt.touch_type)))
     LEFT JOIN public.outcomes lo ON ((lo.code = lt.outcome_code)))
     LEFT JOIN LATERAL ( SELECT max(COALESCE(t.responded_at, t.touched_at)) AS last_spoke_at
           FROM (public.touchpoints t
             LEFT JOIN public.outcomes x ON ((x.code = t.outcome_code)))
          WHERE ((t.contact_id = c.id) AND (COALESCE(x.counts_as_response, false) OR (t.touch_type = 'meeting'::text)))) ls ON (true))
     LEFT JOIN LATERAL ( SELECT r.due_on,
            r.reminder_type
           FROM public.reminders r
          WHERE ((r.contact_id = c.id) AND (r.status = ANY (ARRAY['open'::text, 'snoozed'::text])))
          ORDER BY r.due_on
         LIMIT 1) nr ON (true))
     LEFT JOIN public.reminder_types rt ON ((rt.code = nr.reminder_type)))
     LEFT JOIN LATERAL ( SELECT count(*) AS touches,
            count(*) FILTER (WHERE (t.touch_type = 'email'::text)) AS emails_sent,
            count(*) FILTER (WHERE (t.touch_type = 'call'::text)) AS calls_dialed
           FROM public.touchpoints t
          WHERE (t.contact_id = c.id)) tc ON (true))
     LEFT JOIN LATERAL ( SELECT p.stage,
            p.expected_aum,
            p.funded_aum
           FROM public.opportunities p
          WHERE ((p.contact_id = c.id) OR ((sg.party_type = 'organization'::text) AND (c.organization_id IS NOT NULL) AND (p.organization_id = c.organization_id)))
          ORDER BY (p.stage = ANY (ARRAY['funded'::text, 'lost'::text])), p.opened_on DESC
         LIMIT 1) op ON (true));

-- ===================== 20261003000200_client_views.sql =====================

-- =====================================================================
-- GAARD Capital CRM · Migration 8 of 9 · Client loyalty and benefit groups
--
-- Two of Jon's tabs are lists of people he already won, not prospects:
--
--   v_client_loyalty   funded clients: next Thanksgiving card, next referral
--                      check-in, last loyalty touch, mailing address
--   v_benefit_groups   affiliate benefit groups: plans served, commissions,
--                      shared employers, primary contact, next outreach
--
-- The two reminder types the loyalty view reads (thanksgiving_card,
-- referral_check_in) are reference rows in migration 10.
--
-- First run in the Supabase SQL Editor on Oct 3, 2026; this file was
-- rebuilt from the live schema on Oct 14, 2026.
-- =====================================================================

create or replace view public.v_client_loyalty with (security_invoker = true) as
 SELECT c.id AS contact_id,
    c.full_name,
    COALESCE(o.name, c.employer) AS client,
    sg.name AS segment,
    c.email,
    c.phone,
    COALESCE(c.mailing_address, o.mailing_address) AS mailing_address,
    op.funded_on,
    op.funded_aum,
    tc.due_on AS next_thanksgiving_card,
    rc.due_on AS next_referral_check_in,
    lt.due_on AS last_loyalty_touch_on,
    ltt.label AS last_loyalty_touch,
    tm.full_name AS owner
   FROM ((((((((public.contacts c
     JOIN public.segments sg ON ((sg.code = c.segment_code)))
     LEFT JOIN public.organizations o ON ((o.id = c.organization_id)))
     LEFT JOIN public.team_members tm ON ((tm.id = c.owner_id)))
     LEFT JOIN LATERAL ( SELECT p.funded_on,
            p.funded_aum
           FROM public.opportunities p
          WHERE ((p.contact_id = c.id) OR ((c.organization_id IS NOT NULL) AND (p.organization_id = c.organization_id)))
          ORDER BY (p.stage = 'funded'::text) DESC, p.opened_on DESC
         LIMIT 1) op ON (true))
     LEFT JOIN LATERAL ( SELECT r.due_on
           FROM public.reminders r
          WHERE ((r.contact_id = c.id) AND (r.reminder_type = 'thanksgiving_card'::text) AND (r.status = ANY (ARRAY['open'::text, 'snoozed'::text])))
          ORDER BY r.due_on
         LIMIT 1) tc ON (true))
     LEFT JOIN LATERAL ( SELECT r.due_on
           FROM public.reminders r
          WHERE ((r.contact_id = c.id) AND (r.reminder_type = 'referral_check_in'::text) AND (r.status = ANY (ARRAY['open'::text, 'snoozed'::text])))
          ORDER BY r.due_on
         LIMIT 1) rc ON (true))
     LEFT JOIN LATERAL ( SELECT r.due_on,
            r.reminder_type
           FROM public.reminders r
          WHERE ((r.contact_id = c.id) AND (r.reminder_type = ANY (ARRAY['thanksgiving_card'::text, 'referral_check_in'::text])) AND (r.status = 'done'::text))
          ORDER BY r.due_on DESC
         LIMIT 1) lt ON (true))
     LEFT JOIN public.reminder_types ltt ON ((ltt.code = lt.reminder_type)))
  WHERE (('client'::text = ANY (c.tags)) OR (EXISTS ( SELECT 1
           FROM public.opportunities p
          WHERE ((p.stage = 'funded'::text) AND ((p.contact_id = c.id) OR ((c.organization_id IS NOT NULL) AND (p.organization_id = c.organization_id)))))) OR (EXISTS ( SELECT 1
           FROM public.reminders r
          WHERE ((r.contact_id = c.id) AND (r.reminder_type = ANY (ARRAY['thanksgiving_card'::text, 'referral_check_in'::text]))))));

create or replace view public.v_benefit_groups with (security_invoker = true) as
 SELECT o.id AS organization_id,
    o.name,
    o.org_type,
    o.city,
    o.state,
    o.plans_served,
    o.commissions,
    o.shared_employers,
    o.advertises_retirement,
    cc.people,
    cc.primary_contact,
    cc.primary_email,
    cc.primary_title,
    tt.last_touch_on,
    tt.last_outcome,
    nr.due_on AS next_outreach_on,
    o.do_not_contact,
    o.notes
   FROM (((public.organizations o
     LEFT JOIN LATERAL ( SELECT count(*) AS people,
            (array_agg(c.full_name ORDER BY c.id))[1] AS primary_contact,
            (array_agg(c.email ORDER BY c.id))[1] AS primary_email,
            (array_agg(c.title ORDER BY c.id))[1] AS primary_title
           FROM public.contacts c
          WHERE (c.organization_id = o.id)) cc ON (true))
     LEFT JOIN LATERAL ( SELECT max(public.local_date(t.touched_at)) AS last_touch_on,
            (array_agg(x.label ORDER BY t.touched_at DESC))[1] AS last_outcome
           FROM ((public.touchpoints t
             JOIN public.contacts c ON ((c.id = t.contact_id)))
             LEFT JOIN public.outcomes x ON ((x.code = t.outcome_code)))
          WHERE (c.organization_id = o.id)) tt ON (true))
     LEFT JOIN LATERAL ( SELECT min(r.due_on) AS due_on
           FROM public.reminders r
          WHERE ((r.organization_id = o.id) AND (r.status = ANY (ARRAY['open'::text, 'snoozed'::text])))) nr ON (true))
  WHERE ((o.segment_code = 'AFFILIATE'::text) AND ((o.org_type ~~* '%benefit%'::text) OR ('benefit_group'::text = ANY (o.tags)) OR (o.plans_served IS NOT NULL)));

-- ===================== 20261003000300_review_helpers.sql =====================

-- =====================================================================
-- GAARD Capital CRM · Migration 9 of 9 · Review helpers
--
-- After the workbook import, 275 touchpoints sat in v_outcome_review_queue
-- with free-text outcomes the matcher could not place. These helpers
-- cleared the queue to 2 and rebuilt the follow-ups:
--
-- 1. outcome_aliases.force_review  an alias that is a hint, not a verdict:
--    it suggests the outcome but a person still confirms it
-- 2. match_outcome()               returns that flag
-- 3. rematch_outcomes()            re-runs the matcher over every touchpoint
--    still waiting for review, after new aliases are added
-- 4. merge_contacts(keep, remove)  the same person twice -> one row, with
--    every touch, reminder, opportunity and email moved across
-- 5. rebuild_follow_up_reminders() one open follow-up per organization (or
--    individual), from the latest touch; explicit dates first, then the cadence
-- 6. spread_overdue_follow_ups(n)  re-dates the overdue backlog over n weeks
--
-- First run in the Supabase SQL Editor on Oct 3, 2026; this file was
-- rebuilt from the live schema on Oct 14, 2026.
-- =====================================================================

alter table public.outcome_aliases
  add column if not exists force_review boolean not null default false;
comment on column public.outcome_aliases.force_review is 'true: the phrase only suggests the outcome; the touchpoint still goes to the review queue';

-- the return type gains a column, so the old version has to go first
drop function if exists public.match_outcome(text);
create or replace function public.match_outcome(p_text text, OUT outcome_code text, OUT is_exact boolean, OUT phrase text, OUT force_review boolean) RETURNS record
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $_$
  select a.outcome_code,
         norm_text(regexp_replace(p_text, '[\s.!]+$', '')) = a.phrase and not a.force_review,
         a.phrase,
         a.force_review
    from outcome_aliases a
   where norm_text(p_text) ~ ('\m' || regexp_replace(a.phrase, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') || '\M')
   order by length(a.phrase) desc
   limit 1
$_$;

create or replace function public.rematch_outcomes() RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'extensions'
    AS $$
declare
  t        record;
  m        record;
  n_conf   int := 0;
  n_sugg   int := 0;
  n_rem    int;
begin
  perform set_config('app.history_load', 'on', true);       -- facts yes, reminders at the end
  for t in
    select tp.id, tp.touch_type, tp.outcome_raw, tp.ai_suggested_outcome
      from touchpoints tp
     where tp.outcome_status = 'needs_review' and nullif(trim(tp.outcome_raw), '') is not null
     order by tp.touched_at, tp.id
  loop
    select * into m from match_outcome(t.outcome_raw);
    continue when m.outcome_code is null
              or not exists (select 1 from outcomes o where o.code = m.outcome_code and t.touch_type = any (o.applies_to));
    if m.is_exact then
      update touchpoints
         set outcome_code = m.outcome_code, outcome_status = 'confirmed',
             ai_suggested_outcome = null, ai_confidence = null,
             ai_reason = format('Matched "%s" (alias added after the import)', m.phrase),
             confirmed_at = now()
       where id = t.id;
      n_conf := n_conf + 1;
    elsif t.ai_suggested_outcome is distinct from m.outcome_code then
      update touchpoints
         set ai_suggested_outcome = m.outcome_code, ai_confidence = 0.6,
             ai_reason = format('Matched "%s" in the sheet', m.phrase)
       where id = t.id;
      n_sugg := n_sugg + 1;
    end if;
  end loop;
  perform set_config('app.history_load', 'off', true);
  n_rem := rebuild_follow_up_reminders();
  return jsonb_build_object(
    'confirmed',        n_conf,
    'new_suggestions',  n_sugg,
    'still_in_review',  (select count(*) from touchpoints where outcome_status = 'needs_review'),
    'follow_ups_built', n_rem);
end $$;

create or replace function public.merge_contacts(p_keep bigint, p_remove bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  k contacts;
  r contacts;
  v_moved_touches int; v_moved_reminders int; v_moved_opps int := 0; v_dropped_opps int := 0;
begin
  if p_keep = p_remove then raise exception 'keep and remove are the same contact'; end if;
  select * into k from contacts where id = p_keep;
  if not found then raise exception 'Contact % (keep) not found', p_keep; end if;
  select * into r from contacts where id = p_remove;
  if not found then raise exception 'Contact % (remove) not found', p_remove; end if;

  update touchpoints set contact_id = p_keep,
         organization_id = coalesce(k.organization_id, organization_id)
   where contact_id = p_remove;
  get diagnostics v_moved_touches = row_count;

  update reminders set contact_id = p_keep,
         organization_id = coalesce(k.organization_id, organization_id)
   where contact_id = p_remove;
  get diagnostics v_moved_reminders = row_count;

  update email_messages set contact_id = p_keep where contact_id = p_remove;
  update import_rows set contact_id = p_keep where contact_id = p_remove;
  update import_rows set review_candidate_contact_id = p_keep where review_candidate_contact_id = p_remove;
  update contacts set referred_by_contact_id = p_keep where referred_by_contact_id = p_remove;

  -- opportunities: at most one open per person; a duplicate open deal is folded into the kept one
  if exists (select 1 from opportunities where contact_id = p_remove and stage not in ('funded', 'lost'))
     and exists (select 1 from opportunities where contact_id = p_keep and stage not in ('funded', 'lost')) then
    update opportunities o
       set notes = concat_ws(E'\n', o.notes, 'Merged a duplicate open opportunity from contact #' || p_remove
                                               || coalesce(': ' || d.notes, ''))
      from opportunities d
     where o.contact_id = p_keep and o.stage not in ('funded', 'lost')
       and d.contact_id = p_remove and d.stage not in ('funded', 'lost');
    update reminders set opportunity_id = (select id from opportunities where contact_id = p_keep and stage not in ('funded', 'lost') limit 1)
     where opportunity_id in (select id from opportunities where contact_id = p_remove and stage not in ('funded', 'lost'));
    delete from opportunities where contact_id = p_remove and stage not in ('funded', 'lost');
    get diagnostics v_dropped_opps = row_count;
  end if;
  update opportunities set contact_id = p_keep,
         organization_id = coalesce(organization_id, k.organization_id)
   where contact_id = p_remove;
  get diagnostics v_moved_opps = row_count;

  update contacts
     set first_name            = coalesce(first_name, r.first_name),
         last_name             = coalesce(last_name, r.last_name),
         title                 = coalesce(title, r.title),
         employer              = coalesce(employer, r.employer),
         email                 = coalesce(email, r.email),
         phone                 = coalesce(phone, r.phone),
         linkedin_url          = coalesce(linkedin_url, r.linkedin_url),
         linkedin_connected_on = coalesce(linkedin_connected_on, r.linkedin_connected_on),
         city                  = coalesce(city, r.city),
         state                 = coalesce(state, r.state),
         mailing_address       = coalesce(mailing_address, r.mailing_address),
         prospect_aum          = coalesce(prospect_aum, r.prospect_aum),
         source_channel_code   = coalesce(source_channel_code, r.source_channel_code),
         source_detail         = coalesce(source_detail, r.source_detail),
         sourced_on            = least(coalesce(sourced_on, r.sourced_on), coalesce(r.sourced_on, sourced_on)),
         activity_status       = coalesce(activity_status, r.activity_status),
         newsletter_status     = case when r.newsletter_status = 'subscribed' and newsletter_status = 'not_subscribed'
                                      then 'subscribed' else newsletter_status end,
         newsletter_added_on   = coalesce(newsletter_added_on, r.newsletter_added_on),
         newsletter_added_via  = coalesce(newsletter_added_via, r.newsletter_added_via),
         do_not_contact        = do_not_contact or r.do_not_contact,
         dnc_reason            = coalesce(dnc_reason, r.dnc_reason),
         tags                  = (select coalesce(array_agg(distinct x), '{}') from unnest(tags || r.tags) x),
         notes                 = concat_ws(E'\n', notes,
                                   case when r.email is not null and email is not null and norm_email(r.email) <> norm_email(email)
                                        then 'Also uses: ' || r.email end,
                                   r.notes,
                                   'Merged with contact #' || p_remove || coalesce(' (' || r.legacy_ref || ')', ''))
   where id = p_keep;

  delete from contacts where id = p_remove;
  return jsonb_build_object('kept', p_keep, 'removed', p_remove, 'touches_moved', v_moved_touches,
                            'reminders_moved', v_moved_reminders, 'opportunities_moved', v_moved_opps,
                            'duplicate_open_opportunities_folded', v_dropped_opps);
end $$;

create or replace function public.rebuild_follow_up_reminders() RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  t touchpoints;
  n int := 0;
  v_types text[] := '{follow_up,ooo_follow_up,post_call,event_follow_up,referral_follow_up,check_in,fix_contact_info,find_new_contact,onboarding_task}';
begin
  -- pass 1: explicit dates
  for t in
    select distinct on (tp.contact_id) tp.*
      from touchpoints tp
      join contacts c on c.id = tp.contact_id
      left join organizations o on o.id = c.organization_id
     where tp.outcome_status = 'confirmed' and tp.outcome_code is not null and tp.follow_up_on is not null
       and not c.do_not_contact
       and coalesce(o.reach_out_again, true)
       and not exists (select 1 from touchpoints t2 where t2.contact_id = tp.contact_id and t2.touched_at > tp.touched_at)
       and not exists (select 1 from reminders r where r.contact_id = tp.contact_id
                          and r.status in ('open', 'snoozed') and r.reminder_type = any (v_types))
     order by tp.contact_id, tp.touched_at desc, tp.id desc
  loop
    perform apply_outcome_rules(t);
    n := n + 1;
  end loop;

  -- pass 2: the cadence, once per organization (or individual)
  for t in
    select distinct on (coalesce(c.organization_id, -tp.contact_id)) tp.*
      from touchpoints tp
      join contacts c on c.id = tp.contact_id
      left join organizations o on o.id = c.organization_id
     where tp.outcome_status = 'confirmed' and tp.outcome_code is not null
       and not c.do_not_contact
       and coalesce(o.reach_out_again, true)
       and not exists (
             select 1 from reminders r
             join contacts c2 on c2.id = r.contact_id
            where r.status in ('open', 'snoozed') and r.reminder_type = any (v_types)
              and (r.contact_id = tp.contact_id
                   or (c.organization_id is not null and c2.organization_id = c.organization_id)))
     order by coalesce(c.organization_id, -tp.contact_id),
              exists (select 1 from opportunities op where op.contact_id = tp.contact_id and op.stage not in ('funded', 'lost')) desc,
              tp.touched_at desc, tp.id desc
  loop
    perform apply_outcome_rules(t);
    n := n + 1;
  end loop;
  return n;
end $$;

create or replace function public.spread_overdue_follow_ups(p_weeks integer DEFAULT 6) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  n int;
begin
  with overdue as (
    select id, row_number() over (order by due_on, id) - 1 as rn, count(*) over () as total
      from reminders
     where status = 'open' and due_on < local_today()
       and reminder_type in ('follow_up', 'ooo_follow_up', 'post_call', 'event_follow_up', 'referral_follow_up', 'check_in')
  ),
  slots as (
    select d as day, row_number() over (order by d) - 1 as slot
      from generate_series(local_today(), local_today() + (p_weeks * 7 - 1), interval '1 day') d
     where extract(isodow from d) < 6
  )
  update reminders r
     set due_on = s.day,
         details = concat_ws(E'\n', r.details, 'Was due ' || to_char(r.due_on, 'Mon DD, YYYY') || '; re-dated with the backlog')
    from overdue o
    join slots s on s.slot = floor(o.rn * (select count(*) from slots)::numeric / greatest(o.total, 1))
   where r.id = o.id;
  get diagnostics n = row_count;
  return n;
end $$;


