-- one row per workbook tab: how import_gaard_tab(<uploaded table>, <tab>) reads it
insert into public.import_tab_profiles (tab, description, segment, channel_code, touch_type, org_type, default_outcome_code, follow_up_days, tags, match_by_name, header_map, prep_notes, sort_order) values
  ('Affiliates', 'Main table of the Affiliates tab (rows 1-51): partners GAARD reaches out to. "Services" becomes the organization sub-type.', 'Affiliate', 'COLD_EMAIL', 'email', null, null, null, array['affiliate'], false, '{}'::jsonb, 'Export rows 1 to the "data ends" row only. The four small lists further down the tab are separate CSVs (see the Affiliates: ... profiles).', 10),
  ('Affiliates: Fundraising Software', 'The "Fundraising Software" list lower on the Affiliates tab.', 'Affiliate', 'COLD_EMAIL', 'email', 'Fundraising software', null, null, array['affiliate'], false, '{}'::jsonb, 'Headers: Organization, Contact, Email, Website, LinkedIn. Put a real header on every column before exporting.', 11),
  ('Affiliates: Nonprofit Consulting', 'The "Nonprofit Consulting" lists lower on the Affiliates tab.', 'Affiliate', 'COLD_EMAIL', 'email', 'Nonprofit consulting', null, null, array['affiliate'], false, '{}'::jsonb, 'One of these lists has an organization name typed where a header should be: replace it with "Organization".', 12),
  ('Affiliates: Consulting', 'The "Consulting" list lower on the Affiliates tab.', 'Affiliate', 'COLD_EMAIL', 'email', 'Consulting', null, null, array['affiliate'], false, '{}'::jsonb, null, 13),
  ('Individuals and Small Biz', 'Individuals (OCIO / robo) and small businesses. The "Type" column picks the segment per row (Individual, Robo, Small Biz / 401(k)).', 'OCIO', 'COLD_EMAIL', 'email', null, null, null, '{}', false, '{}'::jsonb, 'Make sure every row has a Type. Rows without one are treated as OCIO individuals.', 20),
  ('Benefit Groups', 'Benefits brokers and consultants who can introduce 401(k) plans. Plans Served, Commissions, Shared Employers and Advertises Retirement are kept on the organization.', 'Affiliate', 'COLD_EMAIL', 'email', 'Benefit group', null, null, array['benefit_group', '401k_channel'], false, '{}'::jsonb, 'Commissions may be a formatted dollar amount; that is fine.', 30),
  ('Wrong Emails', 'Contacts whose email bounced. Every row is marked bounced (email_status) and gets a "fix contact info" reminder.', 'Nonprofit', 'COLD_EMAIL', 'email', null, 'BOUNCED', null, '{}', false, '{"a": "outcome"}'::jsonb, 'The top table is a FILTER of the master list, so the master import already marks those; import this tab only for rows that exist nowhere else (the second table). Rename the "a" header to "Outcome" or leave it (mapped here).', 40),
  ('Master List 2025', 'Master List Cold Nonprofits 2025: 2025 outreach plus, in the NEW CONTACT columns, the person re-sourced for 2026. Each row becomes the 2025 contact and, when the NEW columns are filled, a second contact at the same organization (no 2026 touch yet: the 2026 tab brings it).', 'Nonprofit', 'COLD_EMAIL', 'email', null, null, null, '{}', false, '{}'::jsonb, 'Type "Date Sourced" into the blank A1 header. Rename the second First Name / Organization / Website / NOTES headers to "NEW First Name", "NEW Organization", "NEW Website", "NEW NOTES". Export rows 1 to "data ends" (about 1,800) and columns A to W only; delete the color legend and anything to the right.', 50),
  ('Cold Nonprofits 2026', 'Cold Nonprofits 2026: the re-sourced contacts and their 2026 outcome (the dropdown values are all recognized). "Response Notes" is kept as the reply text.', 'Nonprofit', 'COLD_EMAIL', 'email', null, null, null, '{}', false, '{}'::jsonb, 'Export columns A to M only (the color legend in P-Q and the formula note in X are not data).', 60),
  ('Next Step Outreach', 'Main table of the Next Step Outreach tab: people who responded and were moved out of the cold list. Initial Outcome, Status, correspondence, Next Reach out Date, newsletter flag and Active/Dorm are all kept.', 'Nonprofit', 'COLD_EMAIL', 'email', null, null, 90, array['next_step'], false, '{}'::jsonb, 'Type "Contacted Date" into the blank A1 header. Export rows 1 to "data ends" only. Each titled section below is its own CSV (profiles "Next Step: ...").', 70),
  ('Next Step: Limited CRM Notes', 'Section "Limited CRM Notes" of the Next Step tab.', 'Nonprofit', 'COLD_EMAIL', 'email', null, null, 90, array['next_step', 'limited_crm_notes'], false, '{}'::jsonb, 'Export the section header row and its rows only.', 71),
  ('Next Step: No Endowment', 'Section "No Endowment / No Money - Check back in 6-12 months". Rows without a next reach-out date get one 9 months after the last contact.', 'Nonprofit', 'COLD_EMAIL', 'email', null, 'NOT_NOW', 270, array['next_step', 'no_endowment'], false, '{}'::jsonb, 'Export the section header row and its rows only.', 72),
  ('Next Step: Has Manager', 'Section "Have Endowment and Manager -> Check back in 12 months". Rows without a next reach-out date get one 12 months after the last contact.', 'Nonprofit', 'COLD_EMAIL', 'email', null, 'HAS_ADVISOR', 365, array['next_step', 'has_manager'], false, '{}'::jsonb, 'Export the section header row and its rows only.', 73),
  ('Next Step: Community Foundations', 'Section "Community Foundations" of the Next Step tab.', 'Nonprofit', 'COLD_EMAIL', 'email', 'Community foundation', null, 180, array['next_step', 'community_foundation'], false, '{}'::jsonb, 'Export the section header row and its rows only.', 74),
  ('Next Step: Public Agency', 'Section "Public Agency -> Connect once listed".', 'Other', 'COLD_EMAIL', 'email', 'Public agency', 'NOT_NOW', 180, array['next_step', 'public_agency'], false, '{}'::jsonb, 'Export the section header row and its rows only.', 75),
  ('Next Step: Radar', 'The RADAR list at the bottom of the Next Step tab (Contact Name, Email, Organization, with SENT / need to email in the first column).', 'Nonprofit', 'COLD_EMAIL', 'email', null, null, 90, array['next_step', 'radar'], false, '{}'::jsonb, 'Type "Status" into the blank header above the SENT / need to email column. Export the header row and its rows only.', 76),
  ('Onboarded', 'Onboarded clients: each row becomes a contact, its outreach touch, and an opportunity in the onboarding or funded stage (Sent Onboarding, Account Funded Date, AUM = funded AUM). "Channel" sets how the client was found.', 'Nonprofit', 'COLD_EMAIL', 'email', null, null, null, array['client'], false, '{}'::jsonb, 'If some clients are individuals or 401(k) plans, add a "Segment" column (Individual / 401(k) / Nonprofit); otherwise every row is a nonprofit.', 80),
  ('Customer Loyalty', 'Customer Loyalty: existing clients matched by name to the Onboarded contacts; Thanksgiving Card and Referral Check-in dates become reminders (past dates are logged as done).', 'Nonprofit', 'COLD_EMAIL', 'email', null, null, null, array['client'], true, '{"name": "org", "contact": "contact", "clienttype": "segment"}'::jsonb, 'Delete rows 1-6 so the row with Client Type / Name / Contact / Mailing Address is the header. Rename the second "Referral Check in 2" to "Referral Check in 3". For an individual client, put the person in Contact (Name may repeat it).', 90),
  ('Small Biz - NEW', 'Small Biz - NEW: the 401(k) prospect list. Batch becomes a campaign, DateSent the outreach date, DateDelivered the sourced date, Participants and PlanAssets the organization size.', '401(k)', 'COLD_EMAIL', 'email', null, null, null, array['small_biz_list'], false, '{}'::jsonb, 'Delete the empty column L. Both "Note" and "Notes" are kept.', 100)
on conflict (tab) do update set
  description = excluded.description,
  segment = excluded.segment,
  channel_code = excluded.channel_code,
  touch_type = excluded.touch_type,
  org_type = excluded.org_type,
  default_outcome_code = excluded.default_outcome_code,
  follow_up_days = excluded.follow_up_days,
  tags = excluded.tags,
  match_by_name = excluded.match_by_name,
  header_map = excluded.header_map,
  prep_notes = excluded.prep_notes,
  sort_order = excluded.sort_order;
